// Đồng bộ động toàn bộ ảnh và GIF cùng mã file, không đoán tên bài tập.
const AUTO_IMAGE='images/';const AUTO_VIDEO='videos/';
let autoCatalog=[];
const autoId=file=>file.replace(/\.[^.]+$/,'');
const knownNames={
  '0001-2gPfomN':'Abdominal Crunch',
  '0002-Hy9D21L':'Side Bend',
  '0003-1ZFqTDN':'Reverse Crunch',
  '0006-qaZVsGk':'Crunch',
  '0009-PAgTVaK':'Assisted Triceps Dip',
  '0010-8K0w2yA':'Hanging Knee Raise',
  '0011-03lzqwk':'Hanging Leg Raise',
  '0012-UGhRD1A':'Jackknife Sit-Up',
  '0014-r7cT9YD':'Russian Twist',
  '0015-vrhHa6D':'Assisted Pull-Up',
  '0017-kiJ4Z2K':'Assisted Pull-Up',
  '0019-J60bN17':'Assisted Triceps Dip',
  '0020-xAySMB0':'BOSU Ball Squat',
  '0022-znLogoF':'Barbell Bench Press',
  '0026-W9pFVv1':'Barbell Shoulder Press',
  '0027-eZyBC3j':'Barbell Bent-Over Row',
  '0028-SGY8Zui':'Barbell Deadlift'
};
const equipmentById={
  '0001-2gPfomN':'Không dụng cụ','0003-1ZFqTDN':'Không dụng cụ','0006-qaZVsGk':'Không dụng cụ',
  '0009-PAgTVaK':'Máy tập','0010-8K0w2yA':'Xà','0011-03lzqwk':'Xà','0012-UGhRD1A':'Không dụng cụ',
  '0014-r7cT9YD':'Không dụng cụ','0015-vrhHa6D':'Máy tập','0017-kiJ4Z2K':'Máy tập','0019-J60bN17':'Máy tập',
  '0022-znLogoF':'Thanh đòn','0026-W9pFVv1':'Thanh đòn','0027-eZyBC3j':'Thanh đòn','0028-SGY8Zui':'Thanh đòn'
};
const exerciseMetadata=new Map((Array.isArray(window.GYMAI_EXERCISE_METADATA)?window.GYMAI_EXERCISE_METADATA:[]).map(item=>[item.id,item]));
const equipmentLabels={'cable':'Dây cáp','leverage machine':'Máy đòn bẩy','assisted':'Máy trợ lực','medicine ball':'Bóng y tế','stability ball':'Bóng thăng bằng','band':'Dây đàn hồi','barbell':'Thanh đòn','rope':'Dây thừng','dumbbell':'Tạ đơn','ez barbell':'Đòn EZ','sled machine':'Máy kéo xe','upper body ergometer':'Máy đạp tay','kettlebell':'Tạ ấm','olympic barbell':'Thanh Olympic','weighted':'Tạ phụ','bosu ball':'Bóng BOSU','resistance band':'Dây kháng lực','roller':'Con lăn','skierg machine':'Máy SkiErg','hammer':'Búa tập','smith machine':'Máy Smith','wheel roller':'Bánh xe tập bụng','stationary bike':'Xe đạp tại chỗ','tire':'Lốp xe','trap bar':'Thanh trap bar','elliptical machine':'Máy ellipse','stepmill machine':'Máy leo cầu thang'};
const equipmentTypes=['Không dụng cụ','Xà','Tạ đơn','Tạ ấm','Tạ phụ','Thanh đòn','Thanh Olympic','Đòn EZ','Thanh trap bar','Dây cáp','Dây đàn hồi','Dây kháng lực','Dây thừng','Máy đòn bẩy','Máy trợ lực','Máy kéo xe','Máy Smith','Máy đạp tay','Máy SkiErg','Xe đạp tại chỗ','Máy ellipse','Máy leo cầu thang','Bóng y tế','Bóng thăng bằng','Bóng BOSU','Con lăn','Bánh xe tập bụng','Búa tập','Lốp xe'];
function equipmentFor(id){const item=exerciseMetadata.get(id),raw=(item?.equipment||'').toLowerCase(),name=(item?.name||'').toLowerCase();if(raw==='body weight')return /(pull[ -]?up|chin[ -]?up|hanging)/.test(name)?'Xà':'Không dụng cụ';return equipmentLabels[raw]||equipmentById[id]||'Chưa phân loại'}
const autoLabel=file=>exerciseMetadata.get(autoId(file))?.name||knownNames[autoId(file)]||`Bài tập #${file.match(/^(\d+)/)?.[1]||autoId(file)}`;
async function readFolder(url,ext){const r=await fetch(url);if(!r.ok)throw Error(`Không đọc được ${url}`);const html=await r.text();return [...html.matchAll(new RegExp('href="([^"]+\\.'+ext+')"','gi'))].map(x=>decodeURIComponent(x[1]));}
async function syncAllExercises(){try{const manifest=Array.isArray(window.GYMAI_ASSET_IDS)?window.GYMAI_ASSET_IDS:[];if(manifest.length){autoCatalog=manifest.map((id,index)=>({image:`${id}.jpg`,gif:`${id}.gif`,label:autoLabel(`${id}.jpg`),id,index,equipment:equipmentFor(id)}));}else{const [images,gifs]=await Promise.all([readFolder('images/','jpg'),readFolder('videos/','gif')]);const gifIds=new Set(gifs.map(autoId));autoCatalog=images.filter(x=>gifIds.has(autoId(x))).sort((a,b)=>a.localeCompare(b,undefined,{numeric:true})).map((imageFile,index)=>{const id=autoId(imageFile);const gifFile=gifs.find(x=>autoId(x)===id);return {image:imageFile,gif:gifFile,label:autoLabel(imageFile),id,index,equipment:equipmentFor(id)};});}if(!autoCatalog.length)throw Error('Không có cặp ảnh/GIF');homeAuto();}catch(error){console.error(error);layout(`<div class="card"><h2>Không thể tải thư viện</h2><p class="subtitle">Không tìm thấy manifest bài tập. Hãy kiểm tra file <code>assets-manifest.js</code>.</p></div>`);}}
function autoCard(e){return `<article class="workout-card" onclick="showAutoGuide(${e.index})"><img src="${AUTO_IMAGE+e.image}" alt="${e.label}"><div class="workout-body"><span class="equipment-tag">${e.equipment||equipmentFor(e.id)}</span><h3>${e.label}</h3><p>Ảnh + GIF đã đồng bộ</p><p class="accent" style="margin-top:8px;font-weight:700">Mã: ${e.id.match(/^\d+/)?.[0]||e.id}</p></div></article>`}
function homeAuto(){state.tab='home';layout(`<p class="eyebrow">Thư viện tự động đồng bộ</p><h1 class="page-title">${autoCatalog.length.toLocaleString('vi-VN')} bài tập sẵn sàng</h1><p class="subtitle">Mỗi bài được ghép đúng ảnh và GIF có cùng mã file.</p><section class="hero" style="margin-top:22px"><div><p class="eyebrow" style="color:#dce8ff">VIDEO HƯỚNG DẪN</p><h1>Tập đúng động tác, theo dõi từng bước</h1><p>Chọn một bài để xem ảnh minh họa, GIF chuyển động và checklist an toàn.</p><button class="primary-btn" onclick="goAutoExercises()">Mở toàn bộ thư viện <span>→</span></button></div></section><div class="section-head"><h2>Một số bài trong thư viện</h2><button onclick="goAutoExercises()">Xem tất cả →</button></div><div class="workout-grid">${autoCatalog.slice(0,6).map(autoCard).join('')}</div>`)}
function goAutoExercises(){state.tab='exercises';autoExercisesPage()}
function autoExercisesPage(){const q=(state.search||'').toLowerCase(),selected=state.equipment||'Tất cả';const f=autoCatalog.filter(e=>(selected==='Tất cả'||e.equipment===selected)&&(e.label.toLowerCase().includes(q)||e.id.toLowerCase().includes(q))).sort((a,b)=>equipmentTypes.indexOf(a.equipment)-equipmentTypes.indexOf(b.equipment)||a.id.localeCompare(b.id,undefined,{numeric:true}));const filters=['Tất cả',...equipmentTypes,'Chưa phân loại'];layout(`<p class="eyebrow">Thư viện theo dụng cụ</p><h1 class="page-title">Toàn bộ bài tập</h1><p class="subtitle">Phân loại chi tiết theo từng dụng cụ và từng dòng máy.</p><input class="search" id="auto-search" placeholder="⌕  Tìm theo tên hoặc mã bài tập" value="${state.search||''}"><label class="equipment-select-label">Lọc theo dụng cụ<select class="equipment-select" onchange="setEquipment(this.value)">${filters.map(type=>{const count=type==='Tất cả'?autoCatalog.length:autoCatalog.filter(e=>e.equipment===type).length;return `<option value="${type}" ${selected===type?'selected':''}>${type} (${count})</option>`}).join('')}</select></label><div class="section-head"><h2>${f.length.toLocaleString('vi-VN')} kết quả</h2><span class="tag">Ảnh khớp GIF</span></div><div class="workout-grid auto-grid">${f.map(autoCard).join('')}</div>`);document.querySelector('#auto-search').addEventListener('input',e=>{state.search=e.target.value;autoExercisesPage()})}
function setEquipment(type){state.equipment=type;autoExercisesPage()}
function showAutoGuide(index){const e=autoCatalog[index];if(!e)return;document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeAutoGuide()"><div class="modal technique-modal"><div class="technique-head"><div><p class="eyebrow">HƯỚNG DẪN THEO VIDEO</p><h2>${e.label}</h2><p class="subtitle">Mã đồng bộ: ${e.id}</p></div><button class="icon-btn" onclick="closeAutoGuide()">×</button></div><img class="technique-gif" src="${AUTO_VIDEO+e.gif}" alt="${e.label} — GIF hướng dẫn"><div class="technique-grid"><div><b>Ảnh minh họa</b><p>Đang dùng đúng file ${e.image} trong thư mục images.</p></div><div><b>Video/GIF</b><p>Đang dùng đúng file ${e.gif} trong thư mục videos.</p></div><div><b>Cách tập an toàn</b><p>Khởi động trước, bắt đầu với mức tạ nhẹ, giữ chuyển động chậm và kiểm soát theo GIF.</p></div><div class="warning"><b>Lưu ý</b><p>Không cố vượt qua đau nhói. Nếu chưa nhận diện được động tác, hãy hỏi huấn luyện viên trước khi tăng tạ.</p></div></div><div class="modal-actions"><button class="secondary-btn" onclick="closeAutoGuide()">Đóng</button><button class="primary-btn blue" onclick="addExerciseToSession(${e.index})">+ Thêm vào buổi tập</button></div></div></div>`}
function closeAutoGuide(){document.querySelector('#modal-root').innerHTML=''}
function go(tab){state.tab=tab;if(tab==='home')homeAuto();else if(tab==='exercises')autoExercisesPage();else ({programs,progress,profile}[tab])()}
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>go(b.dataset.tab)));setTimeout(syncAllExercises,0);

// Lưu kế hoạch, set tập và hồ sơ ngay trên thiết bị để app dùng được sau khi tải lại.
const GYMAI_STORE='gymai-v1',defaultUser={name:'Gducky',goal:'Tăng cơ',focus:'Mọi người',height:170,weight:68,days:4};
let gymData=JSON.parse(localStorage.getItem(GYMAI_STORE)||'{"user":null,"session":[],"history":[]}');gymData.user={...defaultUser,...gymData.user};gymData.session=Array.isArray(gymData.session)?gymData.session:[];gymData.history=Array.isArray(gymData.history)?gymData.history:[];
const persist=()=>localStorage.setItem(GYMAI_STORE,JSON.stringify(gymData));const findAuto=id=>autoCatalog.find(x=>x.id===id);const totalVolume=()=>gymData.history.reduce((n,x)=>n+x.volume,0);const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function addExerciseToSession(index){const e=autoCatalog[index];if(!e)return;gymData.session.push({id:e.id,label:e.label,weight:'',reps:'',sets:[]});persist();closeAutoGuide();toast(`Đã thêm ${e.label} vào buổi tập`)}
function updateSessionItem(i,k,v){if(gymData.session[i]){gymData.session[i][k]=v;persist()}}
function removeSessionItem(i){gymData.session.splice(i,1);persist();workoutPage()}
function logSet(i){const x=gymData.session[i],weight=Math.max(0,Number(x?.weight)||0),reps=Math.max(1,Number(x?.reps)||0);if(!x)return;x.sets.push({weight,reps});x.weight='';x.reps='';persist();workoutPage();toast(`Đã lưu set ${x.sets.length} cho ${x.label}`)}
function workoutPage(){state.tab='programs';const n=gymData.session.length;layout(`<p class="eyebrow">Buổi tập đang thực hiện</p><div class="title-row"><div><h1 class="page-title">Kế hoạch hôm nay</h1><p class="subtitle">${n?`${n} bài tập · ${gymData.session.reduce((a,x)=>a+x.sets.length,0)} set đã ghi`:'Chọn bài tập từ thư viện để bắt đầu.'}</p></div><button class="secondary-btn" onclick="goAutoExercises()">+ Thêm bài</button></div>${n?`<div class="session-list">${gymData.session.map((x,i)=>{const e=findAuto(x.id);return `<article class="session-card"><img src="${e?AUTO_IMAGE+e.image:''}" alt=""><div class="session-main"><div class="session-heading"><div><h3>${esc(x.label)}</h3><p>${x.sets.length?x.sets.map(s=>`${s.weight} kg × ${s.reps}`).join(' · '):'Chưa có set nào'}</p></div><button class="text-danger" onclick="removeSessionItem(${i})">Bỏ</button></div><div class="set-entry"><label><span>Kg</span><input type="number" min="0" value="${x.weight}" oninput="updateSessionItem(${i},'weight',this.value)" placeholder="20"></label><label><span>Số lần</span><input type="number" min="1" value="${x.reps}" oninput="updateSessionItem(${i},'reps',this.value)" placeholder="10"></label><button class="primary-btn blue" onclick="logSet(${i})">Lưu set</button></div></div></article>`}).join('')}</div><div class="session-summary"><div><span>Khối lượng buổi tập</span><strong>${gymData.session.reduce((a,x)=>a+x.sets.reduce((b,s)=>b+s.weight*s.reps,0),0).toLocaleString('vi-VN')} kg</strong></div><button class="primary-btn blue" onclick="finishWorkout()">Hoàn thành ✓</button></div>`:`<section class="empty-state"><span>🏋️</span><h2>Bắt đầu buổi tập của bạn</h2><p>Khám phá thư viện, xem GIF kỹ thuật rồi thêm các bài phù hợp vào đây.</p><button class="primary-btn blue" onclick="goAutoExercises()">Mở thư viện bài tập</button></section>`}`)}
function finishWorkout(){const entries=gymData.session.filter(x=>x.sets.length).map(x=>({label:x.label,sets:x.sets,volume:x.sets.reduce((n,s)=>n+s.weight*s.reps,0)}));if(!entries.length){toast('Hãy lưu ít nhất một set trước khi hoàn thành');return}gymData.history.unshift({date:new Date().toISOString(),entries,volume:entries.reduce((n,x)=>n+x.volume,0)});gymData.session=[];persist();toast('Đã hoàn thành buổi tập. Làm tốt lắm! 💪');progress()}
function progress(){state.tab='progress';const sets=gymData.history.reduce((n,w)=>n+w.entries.reduce((a,e)=>a+e.sets.length,0),0);layout(`<p class="eyebrow">Theo dõi kết quả</p><h1 class="page-title">Tiến độ của bạn</h1><p class="subtitle">Dữ liệu được lưu riêng trên thiết bị này.</p><div class="stat-grid" style="margin-top:24px"><div class="stat-card"><span>Buổi hoàn thành</span><strong>${gymData.history.length}</strong><span>từ khi bắt đầu</span></div><div class="stat-card"><span>Tổng khối lượng</span><strong class="accent">${totalVolume().toLocaleString('vi-VN')} kg</strong><span>từ các set đã lưu</span></div><div class="stat-card"><span>Set đã ghi</span><strong>${sets}</strong><span>tất cả bài tập</span></div></div><div class="section-head"><h2>Nhật ký gần đây</h2></div>${gymData.history.length?`<div class="history-list">${gymData.history.slice(0,8).map(w=>`<article class="history-card"><div><h3>${new Date(w.date).toLocaleDateString('vi-VN',{day:'2-digit',month:'long',year:'numeric'})}</h3><p>${w.entries.map(e=>esc(e.label)).join(' · ')}</p></div><strong>${w.volume.toLocaleString('vi-VN')} kg</strong></article>`).join('')}</div>`:`<section class="empty-state compact"><span>📈</span><h2>Chưa có dữ liệu tập</h2><p>Hoàn thành buổi tập đầu tiên để bắt đầu theo dõi kết quả.</p><button class="primary-btn blue" onclick="workoutPage()">Lập buổi tập</button></section>`}`)}
function profile(){state.tab='profile';const u=gymData.user;layout(`<p class="eyebrow">Tài khoản</p><h1 class="page-title">Hồ sơ của bạn</h1><p class="subtitle">Cập nhật để GymAI gợi ý lộ trình sát hơn.</p><form class="profile-form" onsubmit="saveProfile(event)"><div class="profile-card"><div class="profile-avatar">${esc(u.name.slice(0,2).toUpperCase())}</div><div><h2>${esc(u.name)}</h2><p>${esc(u.goal)} · ${u.days} buổi / tuần</p></div></div><label>Tên hiển thị<input name="name" maxlength="30" value="${esc(u.name)}"></label><label>Mục tiêu<select name="goal">${['Tăng cơ','Giảm mỡ','Tăng sức mạnh','Duy trì sức khỏe'].map(x=>`<option ${x===u.goal?'selected':''}>${x}</option>`).join('')}</select></label><div class="form-grid"><label>Chiều cao (cm)<input name="height" type="number" min="100" max="250" value="${u.height}"></label><label>Cân nặng (kg)<input name="weight" type="number" min="25" max="350" value="${u.weight}"></label></div><label>Số buổi tập mỗi tuần<input name="days" type="number" min="1" max="7" value="${u.days}"></label><button class="primary-btn blue" type="submit">Lưu hồ sơ</button></form>`)}
function saveProfile(event){event.preventDefault();const d=new FormData(event.currentTarget);gymData.user={name:(d.get('name')||defaultUser.name).trim()||defaultUser.name,goal:d.get('goal'),height:Number(d.get('height'))||defaultUser.height,weight:Number(d.get('weight'))||defaultUser.weight,days:Number(d.get('days'))||defaultUser.days};persist();toast('Đã lưu hồ sơ');profile()}
function homeAuto(){state.tab='home';const u=gymData.user;layout(`<p class="eyebrow">GymAI · ${new Date().toLocaleDateString('vi-VN',{weekday:'long',day:'numeric',month:'long'})}</p><h1 class="page-title">Chào ${esc(u.name)} 👋</h1><p class="subtitle">Từng set nhỏ tạo nên tiến bộ lớn.</p><section class="hero" style="margin-top:22px"><div><p class="eyebrow" style="color:#dce8ff">BUỔI TẬP HÔM NAY</p><h1>${gymData.session.length?`${gymData.session.length} bài đang chờ bạn`:'Sẵn sàng cho buổi tập mới?'}</h1><p>${gymData.session.length?'Mở kế hoạch, ghi từng set và lưu kết quả.':'Chọn bài từ thư viện, xem GIF kỹ thuật và lập buổi tập theo ý bạn.'}</p><button class="primary-btn" onclick="workoutPage()">${gymData.session.length?'Tiếp tục tập':'Lập buổi tập'} <span>→</span></button></div></section><div class="section-head"><h2>Tiến độ của bạn</h2><button onclick="progress()">Xem chi tiết →</button></div><div class="stat-grid"><div class="stat-card"><span>Buổi tập</span><strong>${gymData.history.length}</strong><span>đã hoàn thành</span></div><div class="stat-card"><span>Khối lượng</span><strong>${totalVolume().toLocaleString('vi-VN')} kg</strong><span>từ lịch sử đã lưu</span></div><div class="stat-card"><span>Thư viện</span><strong>${autoCatalog.length.toLocaleString('vi-VN')}</strong><span>bài có GIF</span></div></div><div class="section-head"><h2>Khám phá bài tập</h2><button onclick="goAutoExercises()">Xem tất cả →</button></div><div class="workout-grid">${autoCatalog.slice(0,6).map(autoCard).join('')}</div>`) }
function programs(){workoutPage()}function go(tab){state.tab=tab;if(tab==='home')homeAuto();else if(tab==='exercises')autoExercisesPage();else if(tab==='programs')workoutPage();else if(tab==='progress')progress();else if(tab==='profile')profile()}

// Màn hình mobile-first: lịch tuần, chương trình gợi ý và phân tích theo tuần.
const starterPrograms=[
  {id:'free',name:'Tập tự do',level:'Tự chọn · Linh hoạt',muscles:'Chọn bất kỳ nhóm cơ',ids:[],image:'0001-2gPfomN.jpg',type:'Tự do'},
  {id:'upper',name:'Thân trên cho người mới',level:'Người mới · 3 buổi / tuần',muscles:'Lưng · Ngực · Vai',ids:['0025-EIeI8Vf','0652-lBDjFxJ','0334-DsgkuIt'],image:'0025-EIeI8Vf.jpg',type:'Người mới'},
  {id:'legs',name:'Ngày chân cho người mới',level:'Người mới · 2 buổi / tuần',muscles:'Chân · Mông · Core',ids:['0043-qXTaZnJ','0032-ila4NZS','0001-2gPfomN'],image:'0043-qXTaZnJ.jpg',type:'Người mới'},
  {id:'full',name:'Toàn thân cân bằng',level:'Người mới · 3 buổi / tuần',muscles:'Chân · Lưng · Ngực · Vai',ids:['0043-qXTaZnJ','0025-EIeI8Vf','0652-lBDjFxJ','0334-DsgkuIt'],image:'0652-lBDjFxJ.jpg',type:'Toàn thân'},
  {id:'push',name:'PUSH DAY',level:'Tăng cơ · 4 buổi / tuần',muscles:'Ngực · Vai · Tay sau',ids:['0025-EIeI8Vf','0334-DsgkuIt'],image:'0025-EIeI8Vf.jpg',type:'Tăng cơ'},
  {id:'pull',name:'PULL DAY',level:'Tăng cơ · 4 buổi / tuần',muscles:'Lưng · Tay trước',ids:['0652-lBDjFxJ','0294-NbVPDMW','0032-ila4NZS'],image:'0652-lBDjFxJ.jpg',type:'Tăng cơ'}
];
const dayNames=['CN','T2','T3','T4','T5','T6','T7'];
function dateKey(d){return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`}
function formatShortDate(d){return d.toLocaleDateString('vi-VN',{day:'numeric',month:'numeric'})}
function weekDays(){const today=new Date(),day=today.getDay(),monday=new Date(today);monday.setDate(today.getDate()-(day===0?6:day-1));return Array.from({length:7},(_,i)=>{const d=new Date(monday);d.setDate(monday.getDate()+i);return d})}
function addProgram(id){const program=starterPrograms.find(x=>x.id===id);if(!program)return;if(!program.ids.length){workoutPage();return}const additions=program.ids.map(id=>findAuto(id)).filter(Boolean);gymData.session.push(...additions.map(e=>({id:e.id,label:e.label,weight:'',reps:'',sets:[]})));persist();toast(`Đã thêm ${additions.length} bài của ${program.name}`);workoutPage()}
function homeAuto(){state.tab='home';const u=gymData.user,today=new Date(),days=weekDays(),sessionText=gymData.session.length?`${gymData.session.length} bài đang chờ`:'Chưa có buổi tập';layout(`<section class="today-head"><div class="today-title"><span class="streak-mark">${Math.max(1,gymData.history.length)}</span><div><p>Hôm nay</p><h1>${today.toLocaleDateString('vi-VN',{weekday:'long',day:'numeric',month:'long'})}</h1></div></div><button class="avatar" onclick="go('profile')">${esc(u.name.slice(0,2).toUpperCase())}</button></section><div class="week-strip">${days.map(d=>`<div class="week-day ${dateKey(d)===dateKey(today)?'today':''}"><b>${dayNames[d.getDay()]}</b><span>${d.getDate()}</span></div>`).join('')}</div><section class="home-hero"><div><span class="hero-kicker">KẾ HOẠCH HÔM NAY</span><h2>${sessionText}</h2><p>${gymData.session.length?'Tiếp tục ghi set để hoàn thành mục tiêu hôm nay.':'Chọn một lịch tập phù hợp rồi bắt đầu theo nhịp của bạn.'}</p><button class="primary-btn" onclick="${gymData.session.length?'workoutPage()':'programs()'}">${gymData.session.length?'Tiếp tục tập':'Chọn lịch tập'} →</button></div></section><div class="quick-grid"><button class="quick-card" onclick="go('progress')"><span>◔</span><div><b>${totalVolume().toLocaleString('vi-VN')} kg</b><small>Tổng volume</small></div></button><button class="quick-card" onclick="go('programs')"><span>✦</span><div><b>${gymData.history.length||0} buổi</b><small>Đã hoàn thành</small></div></button></div><div class="section-head"><h2>Lịch tập của tôi</h2><button onclick="programs()">+ Lịch tập mới</button></div><div class="home-programs">${starterPrograms.slice(0,3).map(p=>`<button class="mini-program" onclick="addProgram('${p.id}')"><img src="${AUTO_IMAGE+p.image}" alt=""><span><b>${p.name}</b><small>${p.muscles}</small><em>${p.level}</em></span><i>›</i></button>`).join('')}</div><div class="section-head"><h2>Bài tập gợi ý</h2><button onclick="goAutoExercises()">Thư viện →</button></div><div class="workout-grid">${autoCatalog.slice(0,3).map(autoCard).join('')}</div>`) }
function programs(){state.tab='programs';const selected=state.programFilter||'Tất cả',filters=['Tất cả','Người mới','Tăng cơ','Toàn thân','Tự do'],items=starterPrograms.filter(p=>selected==='Tất cả'||p.type===selected);layout(`<p class="eyebrow">LỘ TRÌNH TẬP LUYỆN</p><h1 class="page-title">Chương trình phù hợp</h1><p class="subtitle">Chọn lịch sẵn có hoặc tạo buổi tập tự do.</p><div class="program-filter">${filters.map(f=>`<button class="pill ${selected===f?'active':''}" onclick="setProgramFilter('${f}')">${f}</button>`).join('')}</div><section class="program-spotlight"><div><span>✦ GỢI Ý CHO ${esc(gymData.user.name).toUpperCase()}</span><h2>Toàn thân cân bằng</h2><p>3 buổi/tuần · Phù hợp mục tiêu ${esc(gymData.user.goal).toLowerCase()}.</p></div><button onclick="addProgram('full')">Bắt đầu</button></section><div class="program-mobile-list">${items.map(p=>`<article class="program-mobile-card"><img src="${AUTO_IMAGE+p.image}" alt="${p.name}"><div><h2>${p.name}</h2><p>${p.muscles}</p><small>${p.ids.length||'Tự chọn'} bài · ${p.level}</small><button class="secondary-btn" onclick="addProgram('${p.id}')">${p.id==='free'?'Tập tự do':'Chọn lịch'}</button></div></article>`).join('')}</div>`)}
function setProgramFilter(filter){state.programFilter=filter;programs()}
function progress(){state.tab='progress';const days=weekDays(),volumes=Object.fromEntries(days.map(d=>[dateKey(d),0]));gymData.history.forEach(w=>{const k=dateKey(new Date(w.date));if(k in volumes)volumes[k]+=w.volume});const values=days.map(d=>volumes[dateKey(d)]),max=Math.max(...values,1),weekTotal=values.reduce((a,b)=>a+b,0),sets=gymData.history.reduce((n,w)=>n+w.entries.reduce((a,e)=>a+e.sets.length,0),0);layout(`<p class="eyebrow">PHÂN TÍCH</p><h1 class="page-title">Tuần này</h1><p class="subtitle">${formatShortDate(days[0])} — ${formatShortDate(days[6])}</p><section class="volume-card"><div class="volume-title"><span>Volume trong tuần</span><strong>${weekTotal.toLocaleString('vi-VN')} kg</strong></div><div class="weekly-bars">${values.map((v,i)=>`<div><i style="height:${v?Math.max(14,Math.round(v/max*132)):7}px"></i><span>${dayNames[days[i].getDay()]}</span></div>`).join('')}</div><div class="volume-footer"><span>Buổi tập <b>${gymData.history.filter(w=>dateKey(new Date(w.date)) in volumes).length}</b></span><span>Set đã ghi <b>${sets}</b></span></div></section><div class="section-head"><h2>Nhật ký gần đây</h2><button onclick="workoutPage()">Tập tự do →</button></div>${gymData.history.length?`<div class="history-list">${gymData.history.slice(0,6).map(w=>`<article class="history-card"><div><h3>${new Date(w.date).toLocaleDateString('vi-VN',{weekday:'long',day:'numeric',month:'long'})}</h3><p>${w.entries.map(e=>esc(e.label)).join(' · ')}</p></div><strong>${w.volume.toLocaleString('vi-VN')} kg</strong></article>`).join('')}</div>`:`<section class="empty-state compact"><span>◔</span><h2>Chưa có volume tuần này</h2><p>Hoàn thành một buổi để biểu đồ bắt đầu theo dõi bạn.</p><button class="primary-btn blue" onclick="programs()">Chọn chương trình</button></section>`}`)}
function go(tab){state.tab=tab;if(tab==='home')homeAuto();else if(tab==='exercises')autoExercisesPage();else if(tab==='programs')programs();else if(tab==='progress')progress();else if(tab==='profile')profile()}

// Theo dõi buổi tập: set có thể bắt đầu/kết thúc, lưu thời lượng và có đồng hồ nghỉ.
let workoutTicker=null;
function secondsLabel(seconds){const n=Math.max(0,Math.round(seconds||0)),m=Math.floor(n/60),s=n%60;return m?`${m}:${String(s).padStart(2,'0')}`:`${s}s`}
function sessionStarted(){if(!gymData.sessionStartedAt){gymData.sessionStartedAt=Date.now();persist()}return gymData.sessionStartedAt}
function sessionElapsed(){return Math.max(0,(Date.now()-sessionStarted())/1000)}
function restSecondsFor(item,afterExercise=false){if(afterExercise)return 120;const equipment=findAuto(item.id)?.equipment||'';if(['Thanh đòn','Thanh Olympic','Thanh trap bar','Máy Smith','Máy đòn bẩy','Máy kéo xe'].includes(equipment))return 120;if(['Tạ đơn','Tạ ấm','Dây cáp','Máy trợ lực'].includes(equipment))return 90;return 60}
function ensureSessionItem(item){item.targetSets=Math.min(10,Math.max(1,Number(item.targetSets)||3));item.sets=Array.isArray(item.sets)?item.sets:[];item.weight=item.weight??'';item.reps=item.reps??'';return item}
function addExerciseToSession(index){const e=autoCatalog[index];if(!e)return;sessionStarted();gymData.session.push({id:e.id,label:e.label,weight:'',reps:'',targetSets:3,sets:[]});persist();closeAutoGuide();toast(`Đã thêm ${e.label} vào buổi tập`)}
function addProgram(id){const program=starterPrograms.find(x=>x.id===id);if(!program)return;if(!program.ids.length){workoutPage();return}sessionStarted();const additions=program.ids.map(id=>findAuto(id)).filter(Boolean);gymData.session.push(...additions.map(e=>({id:e.id,label:e.label,weight:'',reps:'',targetSets:3,sets:[]})));persist();toast(`Đã thêm ${additions.length} bài của ${program.name}`);workoutPage()}
function updateSessionItem(i,k,v){const item=gymData.session[i];if(!item)return;item[k]=k==='targetSets'?Math.min(10,Math.max(1,Number(v)||1)):v;persist();if(k==='targetSets')workoutPage()}
function startSet(i){const item=gymData.session[i];if(!item)return;ensureSessionItem(item);item.activeSetStartedAt=Date.now();item.restEndsAt=null;persist();workoutPage()}
function completeSet(i){const item=gymData.session[i];if(!item)return;ensureSessionItem(item);const started=Number(item.activeSetStartedAt)||Date.now(),duration=Math.max(1,Math.round((Date.now()-started)/1000)),weight=Math.max(0,Number(item.weight)||0),reps=Math.max(1,Number(item.reps)||0);item.sets.push({weight,reps,durationSeconds:duration,completedAt:Date.now()});item.weight='';item.reps='';item.activeSetStartedAt=null;item.restEndsAt=Date.now()+restSecondsFor(item,item.sets.length>=item.targetSets)*1000;persist();workoutPage();toast(`Đã hoàn thành set ${item.sets.length} · ${secondsLabel(duration)}`)}
function skipRest(i){const item=gymData.session[i];if(!item)return;item.restEndsAt=null;persist();workoutPage()}
function updateWorkoutTimers(){const now=Date.now();document.querySelectorAll('[data-session-timer]').forEach(el=>el.textContent=secondsLabel((now-sessionStarted())/1000));document.querySelectorAll('[data-set-timer]').forEach(el=>{const item=gymData.session[Number(el.dataset.setTimer)];if(item?.activeSetStartedAt)el.textContent=secondsLabel((now-item.activeSetStartedAt)/1000)});document.querySelectorAll('[data-rest-timer]').forEach(el=>{const item=gymData.session[Number(el.dataset.restTimer)],left=item?.restEndsAt?Math.ceil((item.restEndsAt-now)/1000):0;if(left>0)el.textContent=`Nghỉ ${secondsLabel(left)}`;else if(item?.restEndsAt){item.restEndsAt=null;persist();el.textContent='Sẵn sàng cho set tiếp theo'}})}
function beginWorkoutTicker(){if(workoutTicker)clearInterval(workoutTicker);workoutTicker=setInterval(updateWorkoutTimers,1000);updateWorkoutTimers()}
function workoutPage(){state.tab='programs';const count=gymData.session.length;if(!count){if(workoutTicker)clearInterval(workoutTicker);workoutTicker=null;layout(`<p class="eyebrow">Buổi tập đang thực hiện</p><div class="title-row"><div><h1 class="page-title">Kế hoạch hôm nay</h1><p class="subtitle">Chưa có bài tập nào trong buổi này.</p></div><button class="secondary-btn" onclick="goAutoExercises()">+ Thêm bài</button></div><section class="empty-state"><span>🏋️</span><h2>Bắt đầu buổi tập của bạn</h2><p>Chọn lịch có sẵn hoặc thêm bài từ thư viện để ghi set, nghỉ và thời gian tập.</p><button class="primary-btn blue" onclick="programs()">Chọn chương trình</button></section>`);return}sessionStarted();layout(`<div class="workout-top"><div><p class="eyebrow">BUỔI TẬP ĐANG DIỄN RA</p><h1 class="page-title">${count} bài tập hôm nay</h1><p class="subtitle">Thời gian buổi tập: <b data-session-timer>0s</b></p></div><button class="secondary-btn" onclick="goAutoExercises()">+ Bài tập</button></div><div class="session-list workout-session-list">${gymData.session.map((raw,i)=>{const item=ensureSessionItem(raw),e=findAuto(item.id),done=item.sets.length,restLeft=item.restEndsAt?Math.ceil((item.restEndsAt-Date.now())/1000):0,active=Boolean(item.activeSetStartedAt);return `<article class="session-card tracked-session"><img src="${e?AUTO_IMAGE+e.image:''}" alt=""><div class="session-main"><div class="session-heading"><div><span class="equipment-tag">${e?.equipment||''}</span><h3>${esc(item.label)}</h3><p>${done}/${item.targetSets} set hoàn thành</p></div><button class="text-danger" onclick="removeSessionItem(${i})">Bỏ</button></div><div class="set-goal"><label>Set mục tiêu <input type="number" min="1" max="10" value="${item.targetSets}" oninput="updateSessionItem(${i},'targetSets',this.value)"></label><span>${done>=item.targetSets?'✓ Đủ set mục tiêu':'Còn '+(item.targetSets-done)+' set'}</span></div>${done?`<div class="completed-sets">${item.sets.map((s,n)=>`<span>✓ Set ${n+1}: ${s.weight}kg × ${s.reps} · ${secondsLabel(s.durationSeconds)}</span>`).join('')}</div>`:''}${done<item.targetSets?`<div class="set-entry"><label><span>Kg</span><input type="number" min="0" inputmode="decimal" value="${item.weight}" oninput="updateSessionItem(${i},'weight',this.value)" placeholder="20"></label><label><span>Số lần</span><input type="number" min="1" inputmode="numeric" value="${item.reps}" oninput="updateSessionItem(${i},'reps',this.value)" placeholder="10"></label>${active?`<button class="primary-btn blue finish-set" onclick="completeSet(${i})">✓ Hoàn thành</button>`:`<button class="primary-btn blue finish-set" onclick="startSet(${i})">▶ Bắt đầu set</button>`}</div>${active?`<div class="set-status active">⏱ Đang tập: <b data-set-timer="${i}">0s</b></div>`:''}${restLeft>0?`<div class="set-status rest">☕ <b data-rest-timer="${i}">Nghỉ ${secondsLabel(restLeft)}</b><button onclick="skipRest(${i})">Bỏ qua</button></div>`:''}`:`<div class="exercise-complete">✓ Đã hoàn thành ${item.targetSets} set · Nghỉ 2 phút trước khi chuyển bài</div>`}</div></article>`}).join('')}</div><div class="session-summary active-summary"><div><span>Khối lượng đã hoàn thành</span><strong>${gymData.session.reduce((a,x)=>a+(x.sets||[]).reduce((b,s)=>b+s.weight*s.reps,0),0).toLocaleString('vi-VN')} kg</strong></div><button class="primary-btn blue" onclick="finishWorkout()">Kết thúc buổi tập ✓</button></div>`);beginWorkoutTicker()}
function finishWorkout(){if(!gymData.session.length)return;const entries=gymData.session.filter(x=>x.sets?.length).map(x=>({id:x.id,label:x.label,sets:x.sets,volume:x.sets.reduce((n,s)=>n+s.weight*s.reps,0),durationSeconds:x.sets.reduce((n,s)=>n+(s.durationSeconds||0),0)}));if(!entries.length){toast('Hãy hoàn thành ít nhất một set trước khi kết thúc');return}const endedAt=Date.now(),startedAt=sessionStarted(),durationSeconds=Math.max(1,Math.round((endedAt-startedAt)/1000));gymData.history.unshift({date:new Date(endedAt).toISOString(),startedAt,endedAt,durationSeconds,entries,volume:entries.reduce((n,x)=>n+x.volume,0)});gymData.session=[];gymData.sessionStartedAt=null;persist();if(workoutTicker)clearInterval(workoutTicker);workoutTicker=null;toast(`Đã lưu buổi tập · ${secondsLabel(durationSeconds)}`);progress()}

// Calo là ước tính MET: MET × 3,5 × cân nặng (kg) / 200 × số phút vận động.
function metForExercise(item){const equipment=(findAuto(item.id)?.equipment||'').toLowerCase();if(/thanh|máy|sled|smith/.test(equipment))return 6;if(/tạ đơn|tạ ấm|dây cáp|dây đàn|dây kháng/.test(equipment))return 5;if(/không dụng cụ|xà/.test(equipment))return 4.5;return 4.5}
function caloriesForSet(item,set){const seconds=Number(set.durationSeconds)||0,weight=Number(gymData.user.weight)||68;return Math.round(metForExercise(item)*3.5*weight/200*(seconds/60)*10)/10}
function setCalories(item,set){return Number.isFinite(Number(set.calories))?Number(set.calories):caloriesForSet(item,set)}
function sessionCalories(){return gymData.session.reduce((total,item)=>total+(item.sets||[]).reduce((sum,set)=>sum+setCalories(item,set),0),0)}
const workoutPageBeforeCalories=workoutPage;
workoutPage=function(){workoutPageBeforeCalories();document.querySelectorAll('.tracked-session').forEach((card,index)=>{const item=gymData.session[index];if(!item)return;card.querySelectorAll('.completed-sets span').forEach((chip,setIndex)=>{const set=item.sets[setIndex];if(set)chip.textContent+=` · ${setCalories(item,set).toFixed(1)} kcal`})});const summary=document.querySelector('.active-summary > div');if(summary){const calorie=document.createElement('span');calorie.className='calorie-summary';calorie.textContent=`≈ ${sessionCalories().toFixed(1)} kcal vận động`;summary.appendChild(calorie)}};
completeSet=function(i){const item=gymData.session[i];if(!item)return;ensureSessionItem(item);const started=Number(item.activeSetStartedAt)||Date.now(),duration=Math.max(1,Math.round((Date.now()-started)/1000)),weight=Math.max(0,Number(item.weight)||0),reps=Math.max(1,Number(item.reps)||0),set={weight,reps,durationSeconds:duration,completedAt:Date.now()};set.calories=caloriesForSet(item,set);item.sets.push(set);item.weight='';item.reps='';item.activeSetStartedAt=null;item.restEndsAt=Date.now()+restSecondsFor(item,item.sets.length>=item.targetSets)*1000;persist();workoutPage();toast(`Set ${item.sets.length}: ${set.calories.toFixed(1)} kcal · ${secondsLabel(duration)}`)};
finishWorkout=function(){if(!gymData.session.length)return;const entries=gymData.session.filter(x=>x.sets?.length).map(x=>({id:x.id,label:x.label,sets:x.sets,volume:x.sets.reduce((n,s)=>n+s.weight*s.reps,0),durationSeconds:x.sets.reduce((n,s)=>n+(s.durationSeconds||0),0),calories:x.sets.reduce((n,s)=>n+setCalories(x,s),0)}));if(!entries.length){toast('Hãy hoàn thành ít nhất một set trước khi kết thúc');return}const endedAt=Date.now(),startedAt=sessionStarted(),durationSeconds=Math.max(1,Math.round((endedAt-startedAt)/1000)),calories=entries.reduce((n,x)=>n+x.calories,0);gymData.history.unshift({date:new Date(endedAt).toISOString(),startedAt,endedAt,durationSeconds,entries,volume:entries.reduce((n,x)=>n+x.volume,0),calories});gymData.session=[];gymData.sessionStartedAt=null;persist();if(workoutTicker)clearInterval(workoutTicker);workoutTicker=null;toast(`Đã lưu buổi tập · ${calories.toFixed(1)} kcal`);progress()};

// Chỉ tính thời gian, nghỉ và calo sau khi người dùng bấm bắt đầu buổi tập.
sessionStarted=function(){return gymData.workoutStartedAt||Date.now()};
function startWorkout(){if(!gymData.session.length){toast('Hãy thêm ít nhất một bài tập trước');return}gymData.workoutStartedAt=Date.now();persist();toast('Buổi tập đã bắt đầu. Chúc bạn tập tốt!');workoutPage()}
function workoutReadyPage(){state.tab='programs';if(workoutTicker)clearInterval(workoutTicker);workoutTicker=null;layout(`<p class="eyebrow">SẴN SÀNG TẬP</p><div class="workout-top"><div><h1 class="page-title">Kế hoạch hôm nay</h1><p class="subtitle">${gymData.session.length} bài tập · Đồng hồ sẽ chỉ chạy sau khi bạn bắt đầu.</p></div><button class="secondary-btn" onclick="goAutoExercises()">+ Thêm bài</button></div><section class="ready-banner"><span>◷</span><div><b>Chưa bắt đầu buổi tập</b><p>Hãy kiểm tra bài, số set rồi bấm bắt đầu khi bạn sẵn sàng.</p></div></section><div class="ready-list">${gymData.session.map((raw,i)=>{const item=ensureSessionItem(raw),e=findAuto(item.id);return `<article><img src="${e?AUTO_IMAGE+e.image:''}" alt=""><div><b>${esc(item.label)}</b><span>${item.targetSets} set mục tiêu · ${e?.equipment||'Bài tập'}</span></div><button class="text-danger" onclick="removeSessionItem(${i})">Bỏ</button></article>`}).join('')}</div><button class="start-workout-btn" onclick="startWorkout()">▶ Bắt đầu buổi tập</button><p class="start-note">Thời gian tập, thời gian nghỉ và calo sẽ được tính từ lúc này.</p>`) }
const workoutPageWithCalories=workoutPage;
workoutPage=function(){if(!gymData.workoutStartedAt){workoutReadyPage();return}workoutPageWithCalories()};
const finishWorkoutWithCalories=finishWorkout;
finishWorkout=function(){const hadSession=gymData.session.length;finishWorkoutWithCalories();if(hadSession&&!gymData.session.length){gymData.workoutStartedAt=null;persist()}};
const startSetWithGate=startSet;
startSet=function(i){if(!gymData.workoutStartedAt){toast('Hãy bấm Bắt đầu buổi tập trước');return}startSetWithGate(i)};

// Bộ sưu tập phục hồi: chỉ lấy bài có metadata "stretch" khớp chính xác với ảnh/GIF.
function stretchExercises(){return autoCatalog.filter(item=>/stretch/i.test(item.label))}
function stretchPage(){state.tab='exercises';const q=(state.stretchSearch||'').toLowerCase(),items=stretchExercises().filter(item=>item.label.toLowerCase().includes(q));layout(`<p class="eyebrow">PHỤC HỒI & LINH HOẠT</p><div class="title-row"><div><h1 class="page-title">Bài tập giãn cơ</h1><p class="subtitle">${stretchExercises().length} bài giãn cơ có GIF hướng dẫn, được đối chiếu từ metadata gốc.</p></div><button class="secondary-btn" onclick="goAutoExercises()">Thư viện</button></div><section class="stretch-intro"><span>🧘</span><div><b>Gợi ý sau buổi tập</b><p>Giữ mỗi tư thế 20–40 giây, hít thở đều và không rướn qua ngưỡng đau.</p></div></section><input class="search" id="stretch-search" placeholder="⌕  Tìm giãn cơ đùi, lưng, ngực..." value="${state.stretchSearch||''}"><div class="section-head"><h2>${items.length} bài phù hợp</h2><span class="tag">GIF giãn cơ</span></div><div class="workout-grid auto-grid">${items.map(autoCard).join('')}</div>`);document.querySelector('#stretch-search').addEventListener('input',e=>{state.stretchSearch=e.target.value;stretchPage()})}
const homeAutoBeforeStretch=homeAuto;
homeAuto=function(){homeAutoBeforeStretch();const quick=document.querySelector('.quick-grid');if(!quick)return;quick.insertAdjacentHTML('afterend',`<button class="stretch-cta" onclick="stretchPage()"><span>🧘</span><div><b>Giãn cơ sau tập</b><small>${stretchExercises().length} bài có GIF hướng dẫn</small></div><i>›</i></button>`)};

// Quy trình riêng theo từng bài: chỉ tải dữ liệu hướng dẫn khi người dùng mở bài đó.
let instructionIndex=null,instructionLoadPromise=null;
async function getExerciseSteps(id){if(instructionIndex)return instructionIndex.get(id)||[];if(!instructionLoadPromise){instructionLoadPromise=fetch('data-exercises.json').then(r=>{if(!r.ok)throw Error('Không tải được dữ liệu hướng dẫn');return r.json()}).then(data=>{instructionIndex=new Map(data.map(item=>[item.image.split('/').pop().replace('.jpg',''),item.instruction_steps?.en||[]]));return instructionIndex})}const index=await instructionLoadPromise;return index.get(id)||[]}
autoCard=function(e){return `<article class="workout-card" onclick="showAutoGuide(${e.index})"><img src="${AUTO_IMAGE+e.image}" alt="${esc(e.label)}"><div class="workout-body"><span class="equipment-tag">${e.equipment||equipmentFor(e.id)}</span><h3>${esc(e.label)}</h3></div></article>`};
showAutoGuide=async function(index){const e=autoCatalog[index];if(!e)return;const root=document.querySelector('#modal-root');root.innerHTML=`<div class="modal-backdrop"><div class="modal technique-modal"><div class="technique-head"><div><p class="eyebrow">HƯỚNG DẪN THỰC HIỆN</p><h2>${esc(e.label)}</h2><p class="subtitle">${esc(e.equipment||equipmentFor(e.id))}</p></div><button class="icon-btn" onclick="closeAutoGuide()">×</button></div><img class="technique-gif" src="${AUTO_VIDEO+e.gif}" alt="GIF hướng dẫn ${esc(e.label)}"><div class="instruction-loading">Đang tải quy trình thực hiện…</div></div></div>`;try{const steps=await getExerciseSteps(e.id);if(!root.querySelector('.instruction-loading'))return;root.querySelector('.instruction-loading').outerHTML=steps.length?`<section class="instruction-panel"><h3>Các bước thực hiện</h3><ol class="instruction-list">${steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><p class="instruction-note">Di chuyển có kiểm soát. Dừng lại nếu có đau nhói hoặc khó chịu bất thường.</p></section>`:`<section class="instruction-panel"><h3>Hướng dẫn</h3><p>Chưa tìm thấy các bước chi tiết cho bài này.</p></section>`}catch(error){console.error(error);const loading=root.querySelector('.instruction-loading');if(loading)loading.textContent='Không thể tải quy trình. Hãy kiểm tra file dữ liệu hướng dẫn.'}}

// Các tương tác nhanh của màn hình buổi tập: số liệu trực tiếp, ghi chú và chọn thêm bài.
function completedSetCount(){return gymData.session.reduce((n,item)=>n+(item.sets?.length||0),0)}
function saveSessionNote(value){gymData.sessionNote=value;persist()}
const workoutPageBeforePolish=workoutPage;
workoutPage=function(){workoutPageBeforePolish();if(!gymData.workoutStartedAt)return;const top=document.querySelector('.workout-top');if(!top)return;const volume=gymData.session.reduce((n,item)=>n+(item.sets||[]).reduce((sum,set)=>sum+set.weight*set.reps,0),0);top.insertAdjacentHTML('afterend',`<div class="live-workout-stats"><span><b>${volume.toLocaleString('vi-VN')} kg</b>Volume</span><span><b>${sessionCalories().toFixed(1)}</b>kcal</span><span><b>${completedSetCount()}</b>Hiệp</span></div><textarea class="session-note" placeholder="✎ Ghi chú cho buổi tập hôm nay" oninput="saveSessionNote(this.value)">${esc(gymData.sessionNote||'')}</textarea>`);const add=top.querySelector('.secondary-btn');if(add){add.textContent='+ Thêm bài';add.setAttribute('onclick','openExercisePicker()')}};
let pickerSelected=new Set(),pickerQuery='';
function openExercisePicker(){pickerSelected=new Set();pickerQuery='';renderExercisePicker()}
function renderExercisePicker(){const q=pickerQuery.toLowerCase(),results=autoCatalog.filter(e=>e.label.toLowerCase().includes(q)||e.equipment.toLowerCase().includes(q)).slice(0,80);document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop picker-backdrop" onclick="if(event.target===this)closeAutoGuide()"><div class="exercise-picker"><div class="sheet-handle"></div><div class="picker-head"><div><p class="eyebrow">THÊM VÀO BUỔI TẬP</p><h2>Chọn bài tập</h2></div><button class="icon-btn" onclick="closeAutoGuide()">×</button></div><input class="search picker-search" value="${esc(pickerQuery)}" placeholder="⌕  Tìm tên bài tập hoặc dụng cụ" oninput="pickerSearch(this.value)"><div class="picker-list">${results.map(e=>`<button class="picker-row ${pickerSelected.has(e.id)?'selected':''}" onclick="togglePicker('${e.id}')"><img src="${AUTO_IMAGE+e.image}" alt=""><span><b>${esc(e.label)}</b><small>${esc(e.equipment)}</small></span><i>${pickerSelected.has(e.id)?'✓':'+'}</i></button>`).join('')}</div><button class="picker-confirm" onclick="confirmPicker()">Thêm ${pickerSelected.size||''} bài${pickerSelected.size?'':' tập'}</button></div></div>`}
function pickerSearch(value){pickerQuery=value;renderExercisePicker()}
function togglePicker(id){pickerSelected.has(id)?pickerSelected.delete(id):pickerSelected.add(id);renderExercisePicker()}
function confirmPicker(){const entries=[...pickerSelected].map(id=>findAuto(id)).filter(Boolean);if(!entries.length){toast('Chọn ít nhất một bài tập');return}gymData.session.push(...entries.map(e=>({id:e.id,label:e.label,weight:'',reps:'',targetSets:3,sets:[]})));persist();closeAutoGuide();toast(`Đã thêm ${entries.length} bài tập`);workoutPage()}
function openPreviousWorkout(){const recent=gymData.history.slice(0,5);if(!recent.length){toast('Chưa có buổi tập nào để tải lại');return}document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeAutoGuide()"><div class="exercise-picker previous-sheet"><div class="sheet-handle"></div><div class="picker-head"><div><p class="eyebrow">LỊCH SỬ BUỔI TẬP</p><h2>Tải buổi tập trước</h2></div><button class="icon-btn" onclick="closeAutoGuide()">×</button></div><div class="previous-list">${recent.map((w,i)=>`<button onclick="loadPreviousWorkout(${i})"><b>${new Date(w.date).toLocaleDateString('vi-VN',{day:'numeric',month:'long'})}</b><span>${w.entries.length} bài · ${w.entries.reduce((n,e)=>n+e.sets.length,0)} hiệp · ${w.volume.toLocaleString('vi-VN')} kg</span><i>›</i></button>`).join('')}</div></div></div>`}
function loadPreviousWorkout(index){const previous=gymData.history[index];if(!previous)return;gymData.session=previous.entries.map(entry=>({id:entry.id,label:entry.label,weight:'',reps:'',targetSets:Math.max(3,entry.sets.length),sets:[]}));gymData.workoutStartedAt=null;gymData.sessionNote='';persist();closeAutoGuide();toast('Đã tải lại buổi tập trước');workoutPage()}
const homeAutoBeforePrevious=homeAuto;
homeAuto=function(){homeAutoBeforePrevious();if(!gymData.history.length)return;const stretch=document.querySelector('.stretch-cta');if(stretch)stretch.insertAdjacentHTML('afterend',`<button class="previous-cta" onclick="openPreviousWorkout()"><span>↻</span><div><b>Tải buổi tập trước</b><small>Lặp lại kế hoạch gần nhất của bạn</small></div><i>›</i></button>`)};

// Điều chỉnh từng set và hỗ trợ bài tập thực hiện theo từng bên cơ thể.
function looksLikePerSide(name=''){return /(one[ -]?(arm|leg)|single[ -]?(arm|leg)|alternate|alternating|unilateral|lunge|step[ -]?up|bulgarian|cossack|curtsy|side bend|side lunge)/i.test(name)}
function ensureSideFlag(item){if(typeof item.perSide!=='boolean')item.perSide=looksLikePerSide(item.label);return item.perSide}
function togglePerSide(i){const item=gymData.session[i];if(!item)return;item.perSide=!ensureSideFlag(item);persist();workoutPage()}
function updateCompletedSet(exerciseIndex,setIndex,field,value){const set=gymData.session[exerciseIndex]?.sets?.[setIndex];if(!set)return;set[field]=field==='weight'?Math.max(0,Number(value)||0):Math.max(1,Number(value)||1);persist();workoutPage()}
function removeCompletedSet(exerciseIndex,setIndex){const item=gymData.session[exerciseIndex];if(!item)return;item.sets.splice(setIndex,1);persist();workoutPage();toast('Đã xóa set')}
const completeSetBeforePerSide=completeSet;
completeSet=function(i){const item=gymData.session[i];if(item)ensureSideFlag(item);completeSetBeforePerSide(i);const latest=gymData.session[i]?.sets?.at(-1);if(latest){latest.perSide=Boolean(gymData.session[i].perSide);persist()}};
const workoutPageBeforeSetEditing=workoutPage;
workoutPage=function(){workoutPageBeforeSetEditing();if(!gymData.workoutStartedAt)return;document.querySelectorAll('.tracked-session').forEach((card,i)=>{const item=gymData.session[i];if(!item)return;const perSide=ensureSideFlag(item),repLabel=perSide?'Lần / bên':'Số lần';const repInputLabel=card.querySelector('.set-entry label:nth-child(2) span');if(repInputLabel)repInputLabel.textContent=repLabel;const goal=card.querySelector('.set-goal');if(goal&&!goal.querySelector('.side-toggle'))goal.insertAdjacentHTML('beforeend',`<button class="side-toggle ${perSide?'active':''}" onclick="togglePerSide(${i})">${perSide?'↔ Mỗi bên':'↔ Tổng số lần'}</button>`);const completed=card.querySelector('.completed-sets');if(completed&&item.sets.length){completed.innerHTML=item.sets.map((set,j)=>`<div class="set-edit-row"><span>✓ ${j+1}</span><label><input type="number" min="0" value="${set.weight}" onchange="updateCompletedSet(${i},${j},'weight',this.value)"><em>kg</em></label><label><input type="number" min="1" value="${set.reps}" onchange="updateCompletedSet(${i},${j},'reps',this.value)"><em>${set.perSide??perSide?'lần/bên':'lần'}</em></label><small>${secondsLabel(set.durationSeconds)} · ${setCalories(item,set).toFixed(1)} kcal</small><button onclick="removeCompletedSet(${i},${j})" aria-label="Xóa set">×</button></div>`).join('')}})};

// Giai đoạn lập kế hoạch: chỉnh từng bài và từng set trước khi đồng hồ được phép chạy.
function ensurePresetSets(item){ensureSessionItem(item);if(!Array.isArray(item.presetSets))item.presetSets=[];while(item.presetSets.length<item.targetSets)item.presetSets.push({weight:'',reps:''});if(item.presetSets.length>item.targetSets)item.presetSets.length=item.targetSets;return item.presetSets}
function updatePlanTitle(value){gymData.sessionTitle=value.slice(0,60);persist()}
function updatePresetSet(exerciseIndex,setIndex,field,value){const item=gymData.session[exerciseIndex];if(!item)return;const presets=ensurePresetSets(item);presets[setIndex][field]=field==='weight'?Math.max(0,Number(value)||0):Math.max(1,Number(value)||1);persist()}
function changePlannedSets(index,delta){const item=gymData.session[index];if(!item)return;item.targetSets=Math.max(1,Math.min(10,(Number(item.targetSets)||3)+delta));ensurePresetSets(item);persist();workoutReadyPage()}
const workoutReadyBeforePlanner=workoutReadyPage;
workoutReadyPage=function(){state.tab='programs';if(workoutTicker)clearInterval(workoutTicker);workoutTicker=null;const title=gymData.sessionTitle||'Tập tự do';layout(`<p class="eyebrow">LẬP KẾ HOẠCH</p><div class="plan-heading"><div><h1 class="page-title">Chuẩn bị buổi tập</h1><p class="subtitle">Chỉnh bài tập và set trước khi bắt đầu.</p></div><button class="secondary-btn" onclick="openExercisePicker()">+ Thêm bài</button></div><input class="plan-title-input" value="${esc(title)}" maxlength="60" placeholder="Tên buổi tập" oninput="updatePlanTitle(this.value)" aria-label="Tên buổi tập"><textarea class="session-note" placeholder="✎ Ghi chú cho buổi tập hôm nay" oninput="saveSessionNote(this.value)">${esc(gymData.sessionNote||'')}</textarea>${gymData.session.length?`<div class="plan-exercise-list">${gymData.session.map((raw,i)=>{const item=ensureSessionItem(raw),e=findAuto(item.id),perSide=ensureSideFlag(item),presets=ensurePresetSets(item);return `<article class="plan-exercise"><div class="plan-exercise-head"><img src="${e?AUTO_IMAGE+e.image:''}" alt=""><div><span class="equipment-tag">${e?.equipment||''}</span><h3>${esc(item.label)}</h3><p>${perSide?'Số lần mỗi bên':'Tổng số lần'}</p></div><button class="text-danger" onclick="removeSessionItem(${i})">Bỏ</button></div><div class="plan-set-head"><b>Set đã chuẩn bị</b><div><button onclick="changePlannedSets(${i},-1)">−</button><span>${item.targetSets}</span><button onclick="changePlannedSets(${i},1)">+</button></div></div><div class="preset-list">${presets.map((set,j)=>`<div><span>Set ${j+1}</span><label><input type="number" min="0" value="${set.weight}" oninput="updatePresetSet(${i},${j},'weight',this.value)" placeholder="kg"><em>kg</em></label><label><input type="number" min="1" value="${set.reps}" oninput="updatePresetSet(${i},${j},'reps',this.value)" placeholder="lần"><em>${perSide?'lần/bên':'lần'}</em></label></div>`).join('')}</div><button class="side-toggle ${perSide?'active':''}" onclick="togglePerSide(${i})">${perSide?'↔ Bài tập mỗi bên':'↔ Bài tập tổng số lần'}</button></article>`}).join('')}</div><button class="start-workout-btn" onclick="startWorkout()">▶ Bắt đầu buổi tập</button><p class="start-note">Bạn vẫn có thể chỉnh từng set khi đang tập. Đồng hồ chỉ bắt đầu sau nút này.</p>`:`<section class="empty-state"><span>＋</span><h2>Tạo buổi tập của bạn</h2><p>Thêm bài từ thư viện hoặc chọn một chương trình có sẵn, rồi chuẩn bị các set trước khi tập.</p><button class="primary-btn blue" onclick="openExercisePicker()">Chọn bài tập</button></section>`}`)};
const startSetBeforePreset=startSet;
startSet=function(i){const item=gymData.session[i];if(item){const next=item.sets?.length||0,preset=ensurePresetSets(item)[next];if(preset){item.weight=preset.weight||'';item.reps=preset.reps||'';persist()}}startSetBeforePreset(i)};
const workoutPageBeforeTitle=workoutPage;
workoutPage=function(){workoutPageBeforeTitle();if(!gymData.workoutStartedAt)return;const heading=document.querySelector('.workout-top .page-title');if(heading&&gymData.sessionTitle)heading.textContent=gymData.sessionTitle};
const homeAutoBeforePlanner=homeAuto;
homeAuto=function(){homeAutoBeforePlanner();const hero=document.querySelector('.home-hero');if(hero&&!hero.querySelector('.plan-link'))hero.insertAdjacentHTML('beforeend',`<button class="plan-link" onclick="workoutReadyPage()">✎ Tạo / chỉnh buổi tập</button>`)};

// Bài giữ tư thế/cardio được theo dõi bằng thời gian thay vì số lần.
function looksTimedExercise(name=''){return /(plank|hold|wall sit|dead hang|hanging|isometric|stretch|bridge hold|run|running|walk|walking|bike|cycling|rowing|jump rope|elliptical|skierg|stair)/i.test(name)}
function ensureTrackingMode(item){if(!item.trackingMode)item.trackingMode=looksTimedExercise(item.label)?'time':'reps';if(item.trackingMode==='time'){ensurePresetSets(item).forEach(set=>{if(!set.durationSeconds)set.durationSeconds=30})}return item.trackingMode}
function toggleTrackingMode(i){const item=gymData.session[i];if(!item)return;item.trackingMode=ensureTrackingMode(item)==='time'?'reps':'time';ensureTrackingMode(item);persist();workoutReadyPage()}
function updateTimedPreset(exerciseIndex,setIndex,value){const item=gymData.session[exerciseIndex];if(!item)return;const seconds=Math.max(5,Math.min(3600,Number(value)||30));ensurePresetSets(item)[setIndex].durationSeconds=seconds;persist()}
const workoutReadyBeforeTimed=workoutReadyPage;
workoutReadyPage=function(){gymData.session.forEach(item=>ensureTrackingMode(item));workoutReadyBeforeTimed();document.querySelectorAll('.plan-exercise').forEach((card,i)=>{const item=gymData.session[i];if(!item)return;const timed=item.trackingMode==='time';const mode=document.createElement('button');mode.className=`mode-toggle ${timed?'active':''}`;mode.textContent=timed?'◷ Theo thời gian':'↻ Theo số lần';mode.setAttribute('onclick',`toggleTrackingMode(${i})`);card.querySelector('.plan-exercise-head div')?.appendChild(mode);if(timed){card.querySelector('.plan-exercise-head p').textContent='Giữ tư thế / thực hiện theo thời gian';const list=card.querySelector('.preset-list');list.innerHTML=ensurePresetSets(item).map((set,j)=>`<div class="timed-preset"><span>Set ${j+1}</span><label><input type="number" min="5" max="3600" value="${set.durationSeconds||30}" oninput="updateTimedPreset(${i},${j},this.value)"><em>giây</em></label><b>${secondsLabel(set.durationSeconds||30)}</b></div>`).join('')}})};
const startSetBeforeTimed=startSet;
startSet=function(i){const item=gymData.session[i];if(item&&ensureTrackingMode(item)==='time'){const next=item.sets?.length||0,preset=ensurePresetSets(item)[next];item.activeTargetSeconds=Math.max(5,Number(preset?.durationSeconds)||30);persist()}startSetBeforeTimed(i)};
const completeSetBeforeTimed=completeSet;
completeSet=function(i){const item=gymData.session[i];if(!item||ensureTrackingMode(item)!=='time'){completeSetBeforeTimed(i);return}const started=Number(item.activeSetStartedAt)||Date.now(),elapsed=Math.max(1,Math.round((Date.now()-started)/1000)),target=Math.max(5,Number(item.activeTargetSeconds)||elapsed),set={weight:0,reps:0,durationSeconds:elapsed,targetSeconds:target,completedAt:Date.now(),perSide:false};set.calories=caloriesForSet(item,set);item.sets.push(set);item.activeSetStartedAt=null;item.activeTargetSeconds=null;item.restEndsAt=Date.now()+restSecondsFor(item,item.sets.length>=item.targetSets)*1000;persist();workoutPage();toast(`Đã hoàn thành ${secondsLabel(elapsed)} · ${set.calories.toFixed(1)} kcal`)};
const updateTimersBeforeTimed=updateWorkoutTimers;
updateWorkoutTimers=function(){updateTimersBeforeTimed();document.querySelectorAll('[data-set-timer]').forEach(el=>{const item=gymData.session[Number(el.dataset.setTimer)];if(item?.activeSetStartedAt&&ensureTrackingMode(item)==='time'){const elapsed=(Date.now()-item.activeSetStartedAt)/1000,left=Math.max(0,Math.ceil((item.activeTargetSeconds||30)-elapsed));el.textContent=left?`Còn ${secondsLabel(left)}`:'Đã hết thời gian'}})};
const workoutPageBeforeTimed=workoutPage;
workoutPage=function(){workoutPageBeforeTimed();if(!gymData.workoutStartedAt)return;document.querySelectorAll('.tracked-session').forEach((card,i)=>{const item=gymData.session[i];if(!item||ensureTrackingMode(item)!=='time')return;const mode=document.createElement('span');mode.className='timed-badge';mode.textContent='◷ Theo thời gian';card.querySelector('.session-heading div')?.appendChild(mode);const entry=card.querySelector('.set-entry'),active=Boolean(item.activeSetStartedAt),target=Math.max(5,Number(item.activeTargetSeconds)||Number(ensurePresetSets(item)[item.sets.length]?.durationSeconds)||30);if(entry)entry.outerHTML=`<div class="timed-set-entry"><label>Thời gian mục tiêu <input type="number" min="5" max="3600" value="${target}" oninput="updateTimedTarget(${i},this.value)"><em>giây · ${secondsLabel(target)}</em></label>${active?`<button class="primary-btn blue finish-set" onclick="completeSet(${i})">✓ Hoàn thành</button>`:`<button class="primary-btn blue finish-set" onclick="startSet(${i})">▶ Bắt đầu set</button>`}</div>`;const completed=card.querySelector('.completed-sets');if(completed)completed.innerHTML=item.sets.map((set,j)=>`<div class="set-edit-row timed-result"><span>✓ ${j+1}</span><label><input type="number" min="5" value="${set.durationSeconds}" onchange="updateCompletedSet(${i},${j},'durationSeconds',this.value)"><em>giây</em></label><b>${secondsLabel(set.durationSeconds)}</b><small>${setCalories(item,set).toFixed(1)} kcal</small><button onclick="removeCompletedSet(${i},${j})" aria-label="Xóa set">×</button></div>`).join('')})};
function updateTimedTarget(i,value){const item=gymData.session[i];if(!item)return;item.activeTargetSeconds=Math.max(5,Math.min(3600,Number(value)||30));persist()}

function guidanceFor(e,steps){const timed=ensureTrackingMode({label:e.label,trackingMode:null,presetSets:[],targetSets:1})==='time';const setup=steps.slice(0,Math.min(2,steps.length)),movement=steps.slice(setup.length);const breath=timed?'Hít thở chậm và đều suốt thời gian giữ tư thế; không nín thở.':'Hít vào khi chuẩn bị hoặc hạ người/tạ; thở ra trong pha gắng sức khi đẩy, kéo hoặc đứng lên.';const safety=timed?'Duy trì tư thế trung lập, dừng ngay nếu đau nhói hoặc tê. Giảm thời gian giữ nếu form bắt đầu mất kiểm soát.':'Chuyển động chậm, kiểm soát toàn bộ biên độ. Bắt đầu với mức nhẹ và dừng khi có đau nhói hoặc mất kỹ thuật.';return {setup,movement,breath,safety}}
showAutoGuide=async function(index){const e=autoCatalog[index];if(!e)return;const root=document.querySelector('#modal-root');root.innerHTML=`<div class="modal-backdrop"><div class="modal technique-modal detailed-guide"><div class="technique-head"><div><p class="eyebrow">HƯỚNG DẪN KỸ THUẬT</p><h2>${esc(e.label)}</h2><p class="subtitle">${esc(e.equipment||equipmentFor(e.id))} · Xem GIF trước khi bắt đầu</p></div><button class="icon-btn" onclick="closeAutoGuide()">×</button></div><img class="technique-gif" src="${AUTO_VIDEO+e.gif}" alt="GIF hướng dẫn ${esc(e.label)}"><div class="instruction-loading">Đang tải hướng dẫn chi tiết…</div></div></div>`;try{const steps=await getExerciseSteps(e.id);if(!root.querySelector('.instruction-loading'))return;const guide=guidanceFor(e,steps),list=items=>items.length?`<ol>${items.map(text=>`<li>${esc(text)}</li>`).join('')}</ol>`:'<p>Thực hiện chậm, đúng biên độ và quan sát GIF minh họa.</p>';root.querySelector('.instruction-loading').outerHTML=`<div class="detail-guidance"><section class="guide-block setup"><div><span>1</span><h3>Tư thế chuẩn bị</h3></div>${list(guide.setup)}</section><section class="guide-block movement"><div><span>2</span><h3>Cách chuyển động</h3></div>${list(guide.movement)}</section><section class="guide-tip"><b>Nhịp thở</b><p>${guide.breath}</p></section><section class="guide-tip warning"><b>An toàn & kiểm soát</b><p>${guide.safety}</p></section></div><div class="modal-actions"><button class="secondary-btn" onclick="closeAutoGuide()">Đóng</button><button class="primary-btn blue" onclick="addExerciseToSession(${e.index});closeAutoGuide()">+ Thêm vào buổi tập</button></div>`}catch(error){console.error(error);const loading=root.querySelector('.instruction-loading');if(loading)loading.textContent='Không thể tải hướng dẫn. Hãy kiểm tra file dữ liệu hướng dẫn.'}}

async function speakExerciseGuide(index){const e=autoCatalog[index];if(!e||!('speechSynthesis' in window)){toast('Thiết bị này chưa hỗ trợ thuyết minh');return}const steps=await getExerciseSteps(e.id);window.speechSynthesis.cancel();const intro=`${e.label}. Hãy quan sát minh họa động và thực hiện lần lượt các bước sau. `;const speech=new SpeechSynthesisUtterance(intro+steps.join(' '));speech.lang='en-US';speech.rate=.88;window.speechSynthesis.speak(speech);toast('Đang phát thuyết minh hướng dẫn')}
function stopExerciseGuide(){if('speechSynthesis' in window)window.speechSynthesis.cancel()}
const showAutoGuideBeforeNarration=showAutoGuide;
showAutoGuide=async function(index){await showAutoGuideBeforeNarration(index);const e=autoCatalog[index],root=document.querySelector('#modal-root');if(!e||!root.querySelector('.detail-guidance'))return;const visual=root.querySelector('.technique-gif');visual?.insertAdjacentHTML('afterend',`<div class="exercise-visual-strip"><img src="${AUTO_IMAGE+e.image}" alt="Minh họa ${esc(e.label)}"><span><b>Minh họa động</b><small>Quan sát GIF để theo dõi hướng chuyển động và biên độ.</small></span></div>`);const guide=root.querySelector('.detail-guidance');guide.insertAdjacentHTML('beforebegin',`<div class="narration-bar"><span>🔊 Thuyết minh từng bước</span><div><button onclick="speakExerciseGuide(${index})">Nghe hướng dẫn</button><button class="stop" onclick="stopExerciseGuide()">Dừng</button></div></div>`)};

// Dự phòng cho máy chủ chỉ phục vụ ảnh/GIF: vẫn có hướng dẫn và thuyết minh khi JSON chi tiết chưa tải được.
function fallbackExerciseSteps(id){const e=autoCatalog.find(item=>item.id===id),timed=e&&looksTimedExercise(e.label);return timed?[`Chọn vị trí ổn định và đặt cơ thể theo đúng tư thế trong hình minh họa của ${e?.label||'bài tập'}.`,`Siết nhẹ cơ trung tâm, giữ cột sống và khớp ở vị trí trung lập.`,`Giữ tư thế trong khoảng thời gian mục tiêu; hít thở chậm, đều và không nín thở.`,`Kết thúc set nếu tư thế mất kiểm soát, xuất hiện đau nhói hoặc tê.`]:[`Chuẩn bị dụng cụ với mức nhẹ, đứng hoặc nằm vững theo tư thế đầu trong GIF của ${e?.label||'bài tập'}.`,`Giữ cơ trung tâm ổn định và khớp thẳng hàng; không dùng đà để bắt đầu động tác.`,`Thực hiện pha chính chậm và có kiểm soát, theo đúng hướng chuyển động trong GIF.`,`Trở về vị trí ban đầu có kiểm soát; hít vào khi chuẩn bị/hạ, thở ra khi gắng sức.`]}
getExerciseSteps=async function(id){if(instructionIndex)return instructionIndex.get(id)||fallbackExerciseSteps(id);if(!instructionLoadPromise){const paths=['data-exercises.json','./data-exercises.json','GYM-AI-package/data-exercises.json'];instructionLoadPromise=(async()=>{for(const path of paths){try{const response=await fetch(path);if(!response.ok)continue;const data=await response.json();instructionIndex=new Map(data.map(item=>[item.image.split('/').pop().replace('.jpg',''),item.instruction_steps?.en||[]]));return instructionIndex}catch(error){console.warn(`Không tải được ${path}`,error)}}instructionIndex=new Map();return instructionIndex})()}const index=await instructionLoadPromise;return index.get(id)||fallbackExerciseSteps(id)};
speakExerciseGuide=async function(index){const e=autoCatalog[index];if(!e||!('speechSynthesis' in window)){toast('Thiết bị này chưa hỗ trợ thuyết minh');return}const steps=await getExerciseSteps(e.id);window.speechSynthesis.cancel();const speech=new SpeechSynthesisUtterance(`${e.label}. ${steps.join(' ')}`);speech.lang=/[à-ỹ]/i.test(steps.join(' '))?'vi-VN':'en-US';speech.rate=.88;window.speechSynthesis.speak(speech);toast('Đang phát thuyết minh hướng dẫn')};

// Thư viện lịch tập theo số buổi/tuần và mục tiêu trong hồ sơ.
const trainingSchedules=[
  {id:'full-2',name:'Toàn thân nền tảng',days:2,goal:'Duy trì sức khỏe',level:'Người mới',summary:'2 buổi toàn thân · Phục hồi tốt',plan:[['Toàn thân A',['Chân','Ngực','Lưng','Cơ bụng & core']],['Toàn thân B',['Chân','Vai','Tay trên','Cơ bụng & core']]]},
  {id:'full-3',name:'Toàn thân 3 buổi',days:3,goal:'Tăng cơ',level:'Người mới',summary:'3 buổi toàn thân · Tăng cơ bền vững',plan:[['Toàn thân A',['Chân','Ngực','Lưng']],['Toàn thân B',['Chân','Vai','Tay trên']],['Toàn thân C',['Chân','Ngực','Lưng','Cơ bụng & core']]]},
  {id:'ppl-3',name:'Push Pull Legs',days:3,goal:'Tăng cơ',level:'Trung cấp',summary:'Đẩy · Kéo · Chân',plan:[['Push',['Ngực','Vai','Tay trên']],['Pull',['Lưng','Tay trên','Cẳng tay']],['Legs & Core',['Chân','Bắp chân','Cơ bụng & core']]]},
  {id:'upper-lower-4',name:'Upper / Lower 4 buổi',days:4,goal:'Tăng sức mạnh',level:'Trung cấp',summary:'Thân trên · Thân dưới · Lặp lại',plan:[['Upper A',['Ngực','Lưng','Vai','Tay trên']],['Lower A',['Chân','Bắp chân','Cơ bụng & core']],['Upper B',['Ngực','Lưng','Vai','Cẳng tay']],['Lower B',['Chân','Bắp chân','Cơ bụng & core']]]},
  {id:'hypertrophy-5',name:'Tăng cơ 5 buổi',days:5,goal:'Tăng cơ',level:'Trung cấp',summary:'Volume cao · Nhóm cơ rõ ràng',plan:[['Ngực & Vai',['Ngực','Vai']],['Lưng & Tay',['Lưng','Tay trên','Cẳng tay']],['Chân',['Chân','Bắp chân']],['Upper Pump',['Ngực','Lưng','Vai']],['Core & Conditioning',['Cơ bụng & core','Cardio']]]},
  {id:'ppl-6',name:'PPL 6 buổi',days:6,goal:'Tăng cơ',level:'Nâng cao',summary:'Push · Pull · Legs lặp lại 2 vòng',plan:[['Push 1',['Ngực','Vai','Tay trên']],['Pull 1',['Lưng','Tay trên','Cẳng tay']],['Legs 1',['Chân','Bắp chân','Cơ bụng & core']],['Push 2',['Ngực','Vai','Tay trên']],['Pull 2',['Lưng','Tay trên','Cẳng tay']],['Legs 2',['Chân','Bắp chân','Cơ bụng & core']]]},
  {id:'fatloss-4',name:'Giảm mỡ 4 buổi',days:4,goal:'Giảm mỡ',level:'Mọi cấp độ',summary:'Sức mạnh toàn thân + cardio',plan:[['Toàn thân sức mạnh',['Chân','Ngực','Lưng']],['Cardio & Core',['Cardio','Cơ bụng & core']],['Thân trên',['Ngực','Lưng','Vai','Tay trên']],['Chân & Cardio',['Chân','Bắp chân','Cardio']]]}
];
function recommendedSchedule(){const u=gymData.user,days=Math.min(6,Math.max(2,Number(u.days)||3));return trainingSchedules.reduce((best,plan)=>Math.abs(plan.days-days)+(plan.goal===u.goal?0:1)<Math.abs(best.days-days)+(best.goal===u.goal?0:1)?plan:best,trainingSchedules[0])}
function coverForGroups(groups){return autoCatalog.find(e=>groups.includes(muscleFor(e.id)))||autoCatalog[0]}
function activateTrainingSchedule(id){const plan=trainingSchedules.find(x=>x.id===id);if(!plan)return;gymData.trainingSchedule=id;persist();toast(`Đã chọn ${plan.name}`);programs()}
function startScheduleDay(scheduleId,dayIndex){if(gymData.workoutStartedAt){toast('Hãy kết thúc buổi đang tập trước khi đổi lịch');return}const schedule=trainingSchedules.find(x=>x.id===scheduleId);const day=schedule?.plan[dayIndex];if(!day)return;const [dayName,groups]=day,chosen=[];groups.forEach((group,offset)=>{const candidates=autoCatalog.filter(e=>muscleFor(e.id)===group);const pick=candidates[(dayIndex+offset)%Math.max(candidates.length,1)];if(pick&&!chosen.some(x=>x.id===pick.id))chosen.push(pick)});gymData.session=chosen.map(e=>({id:e.id,label:e.label,weight:'',reps:'',targetSets:3,sets:[]}));gymData.sessionTitle=`${schedule.name} · ${dayName}`;gymData.sessionNote='';gymData.workoutStartedAt=null;persist();toast(`Đã tạo ${dayName}: ${chosen.length} bài tập`);workoutReadyPage()}
programs=function(){state.tab='programs';const recommended=recommendedSchedule(),activeId=gymData.trainingSchedule||recommended.id,active=trainingSchedules.find(x=>x.id===activeId)||recommended;layout(`<p class="eyebrow">CHƯƠNG TRÌNH CÁ NHÂN</p><h1 class="page-title">Lịch tập phù hợp</h1><p class="subtitle">Dựa trên mục tiêu ${esc(gymData.user.goal).toLowerCase()} và ${gymData.user.days} buổi mỗi tuần.</p><section class="recommend-schedule"><div><span>✦ GỢI Ý HÀNG ĐẦU</span><h2>${recommended.name}</h2><p>${recommended.summary}</p><small>${recommended.level} · ${recommended.days} buổi / tuần</small></div><button onclick="activateTrainingSchedule('${recommended.id}')">Chọn lịch</button></section><div class="section-head"><h2>Lịch đang chọn</h2><button onclick="go('profile')">Chỉnh mục tiêu →</button></div><section class="weekly-plan"><div class="weekly-plan-title"><div><h2>${active.name}</h2><p>${active.summary}</p></div><span>${active.days} buổi</span></div><div class="weekly-day-list">${active.plan.map(([name,groups],i)=>{const cover=coverForGroups(groups);return `<article><img src="${AUTO_IMAGE+cover.image}" alt=""><div><b>Ngày ${i+1} · ${name}</b><small>${groups.join(' · ')}</small></div><button onclick="startScheduleDay('${active.id}',${i})">Tạo buổi</button></article>`}).join('')}</div></section><div class="section-head"><h2>Khám phá lịch khác</h2></div><div class="schedule-grid">${trainingSchedules.map(plan=>`<button class="schedule-card ${plan.id===active.id?'active':''}" onclick="activateTrainingSchedule('${plan.id}')"><b>${plan.name}</b><small>${plan.summary}</small><em>${plan.level} · ${plan.days} buổi/tuần</em></button>`).join('')}</div>`)};

// Phân nhóm cơ cho toàn bộ thư viện theo category gốc của từng ảnh/GIF.
const muscleLabels={'chest':'Ngực','back':'Lưng','shoulders':'Vai','upper arms':'Tay trên','lower arms':'Cẳng tay','upper legs':'Chân','lower legs':'Bắp chân','waist':'Cơ bụng & core','cardio':'Cardio','neck':'Cổ'};
const muscleById=new Map(Object.entries(window.GYMAI_EXERCISE_MUSCLES||{}));
const muscleTypes=['Ngực','Lưng','Vai','Tay trên','Cẳng tay','Chân','Bắp chân','Cơ bụng & core','Cardio','Cổ'];
function muscleFor(id){return muscleLabels[muscleById.get(id)]||'Khác'}
autoCard=function(e){const muscle=muscleFor(e.id);return `<article class="workout-card" data-muscle="${muscle}" onclick="showAutoGuide(${e.index})"><img src="${AUTO_IMAGE+e.image}" alt="${esc(e.label)}"><div class="workout-body"><div class="card-tags"><span class="equipment-tag">${e.equipment||equipmentFor(e.id)}</span><span class="muscle-tag">${muscle}</span></div><h3>${esc(e.label)}</h3></div></article>`};
const autoExercisesPageBeforeMuscle=autoExercisesPage;
autoExercisesPage=function(){autoExercisesPageBeforeMuscle();const selected=state.muscle||'Tất cả';const select=document.createElement('label');select.className='muscle-select-label';select.innerHTML=`Nhóm cơ<select class="equipment-select" onchange="setMuscle(this.value)">${['Tất cả',...muscleTypes,'Khác'].map(type=>`<option value="${type}" ${selected===type?'selected':''}>${type} (${type==='Tất cả'?autoCatalog.length:autoCatalog.filter(e=>muscleFor(e.id)===type).length})</option>`).join('')}</select>`;const equipment=document.querySelector('.equipment-select-label');if(equipment)equipment.insertAdjacentElement('afterend',select);let count=0;document.querySelectorAll('.auto-grid .workout-card').forEach(card=>{const visible=selected==='Tất cả'||card.dataset.muscle===selected;card.hidden=!visible;if(visible)count++});const heading=[...document.querySelectorAll('.section-head h2')].find(x=>x.textContent.includes('kết quả'));if(heading)heading.textContent=`${count.toLocaleString('vi-VN')} kết quả`};
function setMuscle(muscle){state.muscle=muscle;autoExercisesPage()}

// Bộ lịch mở rộng: mọi lộ trình dùng chung nguyên tắc an toàn, chỉ khác trọng tâm lựa chọn.
trainingSchedules.push(
  {id:'beginner-men-3',name:'Nam · Nhập môn thể hình',days:3,goal:'Tăng cơ',audience:'Nam',level:'Người mới',summary:'Toàn thân · kỹ thuật nền tảng',plan:[['Toàn thân A',['Chân','Ngực','Lưng']],['Toàn thân B',['Chân','Vai','Tay trên']],['Toàn thân C',['Chân','Lưng','Cơ bụng & core']]]},
  {id:'beginner-women-3',name:'Nữ · Khỏe đẹp nền tảng',days:3,goal:'Tăng cơ',audience:'Nữ',level:'Người mới',summary:'Chân mông · thân trên · core',plan:[['Chân & Mông A',['Chân','Cơ bụng & core']],['Thân trên cân bằng',['Lưng','Ngực','Vai','Tay trên']],['Chân & Mông B',['Chân','Bắp chân','Cơ bụng & core']]]},
  {id:'women-lower-4',name:'Nữ · Thân dưới & mông 4 buổi',days:4,goal:'Tăng cơ',audience:'Nữ',level:'Trung cấp',summary:'2 ngày thân dưới · form khỏe',plan:[['Mông & đùi trước',['Chân','Cơ bụng & core']],['Thân trên',['Lưng','Ngực','Vai']],['Mông & đùi sau',['Chân','Bắp chân']],['Core & cardio',['Cơ bụng & core','Cardio']]]},
  {id:'women-strength-5',name:'Nữ · Sức mạnh toàn diện',days:5,goal:'Tăng sức mạnh',audience:'Nữ',level:'Nâng cao',summary:'Tăng sức mạnh · 5 ngày cân bằng',plan:[['Lower strength',['Chân','Cơ bụng & core']],['Upper strength',['Ngực','Lưng','Vai']],['Cardio phục hồi',['Cardio','Cơ bụng & core']],['Glute & hamstring',['Chân','Bắp chân']],['Upper pump',['Lưng','Vai','Tay trên']]]},
  {id:'men-strength-4',name:'Nam · Sức mạnh nền tảng',days:4,goal:'Tăng sức mạnh',audience:'Nam',level:'Trung cấp',summary:'Upper / Lower · bài nền tảng',plan:[['Upper sức mạnh',['Ngực','Lưng','Vai','Tay trên']],['Lower sức mạnh',['Chân','Bắp chân','Cơ bụng & core']],['Upper volume',['Ngực','Lưng','Vai']],['Lower volume',['Chân','Cơ bụng & core']]]},
  {id:'men-hypertrophy-5',name:'Nam · Tăng cơ cổ điển',days:5,goal:'Tăng cơ',audience:'Nam',level:'Nâng cao',summary:'Ngực · lưng · chân · vai tay',plan:[['Ngực & tay sau',['Ngực','Vai','Tay trên']],['Lưng & tay trước',['Lưng','Tay trên','Cẳng tay']],['Chân',['Chân','Bắp chân']],['Vai & tay',['Vai','Tay trên','Cẳng tay']],['Toàn thân nhẹ',['Chân','Ngực','Lưng','Cơ bụng & core']]]},
  {id:'fatloss-beginner-3',name:'Giảm mỡ cho người mới',days:3,goal:'Giảm mỡ',audience:'Mọi người',level:'Người mới',summary:'Sức mạnh nhẹ · cardio vừa sức',plan:[['Toàn thân A',['Chân','Ngực','Lưng']],['Cardio & core',['Cardio','Cơ bụng & core']],['Toàn thân B',['Chân','Vai','Lưng']]]},
  {id:'home-fit-3',name:'Tập tại nhà không dụng cụ',days:3,goal:'Duy trì sức khỏe',audience:'Mọi người',level:'Người mới',summary:'Linh hoạt · thể lực toàn thân',plan:[['Thân dưới & core',['Chân','Cơ bụng & core']],['Thân trên bodyweight',['Ngực','Vai','Tay trên']],['Cardio toàn thân',['Cardio','Chân','Cơ bụng & core']]]},
  {id:'mobility-2',name:'Phục hồi & linh hoạt',days:2,goal:'Duy trì sức khỏe',audience:'Mọi người',level:'Mọi cấp độ',summary:'Giãn cơ · core · vận động nhẹ',plan:[['Mobility toàn thân',['Cơ bụng & core','Vai','Chân']],['Cardio nhẹ & kéo giãn',['Cardio','Lưng','Chân']]]},
  {id:'athletic-4',name:'Thể lực thể thao 4 buổi',days:4,goal:'Tăng sức mạnh',audience:'Mọi người',level:'Trung cấp',summary:'Sức mạnh · core · điều hòa',plan:[['Lower power',['Chân','Bắp chân','Cơ bụng & core']],['Upper power',['Ngực','Lưng','Vai']],['Conditioning',['Cardio','Cơ bụng & core']],['Toàn thân sức mạnh',['Chân','Ngực','Lưng']]]}
);
recommendedSchedule=function(){const u=gymData.user,days=Math.min(6,Math.max(2,Number(u.days)||3)),focus=u.focus||'Mọi người';return trainingSchedules.reduce((best,plan)=>{const score=x=>Math.abs(x.days-days)+(x.goal===u.goal?0:2)+(x.audience&&x.audience!=='Mọi người'&&x.audience!==focus?1:0)-(x.audience===focus?1:0);return score(plan)<score(best)?plan:best},trainingSchedules[0])};
profile=function(){state.tab='profile';const u=gymData.user;layout(`<p class="eyebrow">TÀI KHOẢN</p><h1 class="page-title">Hồ sơ của bạn</h1><p class="subtitle">Mục tiêu, định hướng và tần suất giúp GymAI gợi ý lịch sát hơn.</p><form class="profile-form" onsubmit="saveProfile(event)"><div class="profile-card"><div class="profile-avatar">${esc(u.name.slice(0,2).toUpperCase())}</div><div><h2>${esc(u.name)}</h2><p>${esc(u.goal)} · ${u.days} buổi / tuần</p></div></div><label>Tên hiển thị<input name="name" maxlength="30" value="${esc(u.name)}"></label><label>Mục tiêu<select name="goal">${['Tăng cơ','Giảm mỡ','Tăng sức mạnh','Duy trì sức khỏe'].map(x=>`<option ${x===u.goal?'selected':''}>${x}</option>`).join('')}</select></label><label>Định hướng chương trình<select name="focus">${['Mọi người','Nam','Nữ'].map(x=>`<option ${x===(u.focus||'Mọi người')?'selected':''}>${x}</option>`).join('')}</select></label><div class="form-grid"><label>Chiều cao (cm)<input name="height" type="number" min="100" max="250" value="${u.height}"></label><label>Cân nặng (kg)<input name="weight" type="number" min="25" max="350" value="${u.weight}"></label></div><label>Số buổi tập mỗi tuần<input name="days" type="number" min="1" max="7" value="${u.days}"></label><button class="primary-btn blue" type="submit">Lưu hồ sơ</button></form>`) };
saveProfile=function(event){event.preventDefault();const d=new FormData(event.currentTarget);gymData.user={name:(d.get('name')||defaultUser.name).trim()||defaultUser.name,goal:d.get('goal'),focus:d.get('focus')||defaultUser.focus,height:Number(d.get('height'))||defaultUser.height,weight:Number(d.get('weight'))||defaultUser.weight,days:Number(d.get('days'))||defaultUser.days};persist();toast('Đã lưu hồ sơ');profile()};

function personalExerciseRecommendations(){const u=gymData.user;let groups=u.goal==='Giảm mỡ'?['Chân','Lưng','Ngực','Cardio','Cơ bụng & core']:u.goal==='Tăng sức mạnh'?['Chân','Lưng','Ngực','Vai','Cơ bụng & core']:u.focus==='Nữ'?['Chân','Chân','Lưng','Vai','Cơ bụng & core']:u.focus==='Nam'?['Ngực','Lưng','Chân','Vai','Tay trên']:['Chân','Lưng','Ngực','Vai','Cơ bụng & core'];const used=new Set(),result=[];groups.forEach((group,offset)=>{const choices=autoCatalog.filter(e=>muscleFor(e.id)===group&&!used.has(e.id));const pick=choices[(offset*7+Number(u.days||3))%Math.max(choices.length,1)];if(pick){used.add(pick.id);result.push({...pick,group})}});return result}
function addPersonalRecommendation(index){const e=autoCatalog[index];if(!e)return;if(gymData.workoutStartedAt){toast('Không thể thêm bài khi buổi tập đang chạy');return}if(gymData.session.some(item=>item.id===e.id)){toast('Bài tập này đã có trong buổi');return}gymData.session.push({id:e.id,label:e.label,weight:'',reps:'',targetSets:3,sets:[]});persist();toast(`Đã thêm ${e.label}`);workoutReadyPage()}
const programsBeforeRecommendations=programs;
programs=function(){programsBeforeRecommendations();const u=gymData.user,recs=personalExerciseRecommendations(),bmi=u.height&&u.weight?(u.weight/((u.height/100)**2)).toFixed(1):'—',target=document.querySelector('.weekly-plan');if(!target)return;const rationale=u.goal==='Giảm mỡ'?'Ưu tiên bài đa khớp, cardio vừa sức và core.':u.goal==='Tăng sức mạnh'?'Ưu tiên động tác nền tảng, tăng tải từ từ và nghỉ đủ.':'Ưu tiên nhóm cơ lớn, kỹ thuật chuẩn và volume tăng dần.';target.insertAdjacentHTML('beforebegin',`<section class="personal-insight"><div><span>PHÂN TÍCH CÁ NHÂN</span><h2>Gợi ý bài phù hợp cho ${esc(u.name)}</h2><p>${rationale}</p></div><div class="insight-stat"><b>${bmi}</b><small>BMI tham khảo</small></div></section><div class="recommendation-note">Dựa trên: ${esc(u.goal)} · ${esc(u.focus||'Mọi người')} · ${u.days} buổi/tuần. Đây là gợi ý tập luyện phổ thông, hãy điều chỉnh nếu có chấn thương hoặc chỉ định y tế.</div><div class="personal-exercise-grid">${recs.map((e,i)=>`<article><img src="${AUTO_IMAGE+e.image}" alt="${esc(e.label)}"><div><span>${e.group}</span><b>${esc(e.label)}</b><small>${e.equipment||'Không dụng cụ'} · 3 set gợi ý</small></div><button onclick="addPersonalRecommendation(${e.index})">+ Thêm</button></article>`).join('')}</div><div class="section-head"><h2>Lịch tập đang đề xuất</h2></div>`)};
trainingSchedules.push(
  {id:'one-day-reset',name:'1 buổi · Khởi động lại',days:1,goal:'Duy trì sức khỏe',audience:'Mọi người',level:'Người mới',summary:'Toàn thân nhẹ · bắt đầu thói quen',plan:[['Toàn thân nền tảng',['Chân','Ngực','Lưng','Cơ bụng & core']]]},
  {id:'advanced-7',name:'7 ngày · Hiệu năng nâng cao',days:7,goal:'Tăng sức mạnh',audience:'Mọi người',level:'Nâng cao',summary:'6 ngày tạ + 1 ngày phục hồi chủ động',plan:[['Push sức mạnh',['Ngực','Vai','Tay trên']],['Pull sức mạnh',['Lưng','Tay trên','Cẳng tay']],['Legs sức mạnh',['Chân','Bắp chân']],['Cardio & mobility',['Cardio','Cơ bụng & core']],['Upper volume',['Ngực','Lưng','Vai']],['Lower volume',['Chân','Bắp chân','Cơ bụng & core']],['Phục hồi chủ động',['Cardio','Vai','Lưng']]]}
);
recommendedSchedule=function(){const u=gymData.user,days=Math.min(7,Math.max(1,Number(u.days)||3)),focus=u.focus||'Mọi người';return trainingSchedules.reduce((best,plan)=>{const score=x=>Math.abs(x.days-days)+(x.goal===u.goal?0:2)+(x.audience&&x.audience!=='Mọi người'&&x.audience!==focus?1:0)-(x.audience===focus?1:0);return score(plan)<score(best)?plan:best},trainingSchedules[0])};

// Chuỗi tập luyện và nhật ký dinh dưỡng được lưu cùng hồ sơ trên thiết bị.
gymData.nutrition=Array.isArray(gymData.nutrition)?gymData.nutrition:[];
function dayKey(value){const d=new Date(value);return `${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}`}
function trainingStreak(){const trained=new Set(gymData.history.map(x=>dayKey(x.date))),now=new Date(),today=dayKey(now);if(!trained.has(today))now.setDate(now.getDate()-1);let streak=0;while(trained.has(dayKey(now))){streak++;now.setDate(now.getDate()-1)}return streak}
function nutritionTargets(){const u=gymData.user,base=Math.round((Number(u.weight)||65)*30),goal=u.goal;const calories=Math.max(1200,base+(goal==='Tăng cơ'?250:goal==='Giảm mỡ'?-350:goal==='Tăng sức mạnh'?120:0)),protein=Math.round((Number(u.weight)||65)*1.6),fat=Math.round((Number(u.weight)||65)*.8),carbs=Math.max(80,Math.round((calories-protein*4-fat*9)/4));return{calories,protein,fat,carbs}}
function todayNutrition(){const today=dayKey(new Date());return gymData.nutrition.filter(x=>dayKey(x.date)===today).reduce((total,x)=>({kcal:total.kcal+Number(x.kcal||0),protein:total.protein+Number(x.protein||0),carbs:total.carbs+Number(x.carbs||0),fat:total.fat+Number(x.fat||0)}),{kcal:0,protein:0,carbs:0,fat:0})}
function saveFood(event){event.preventDefault();const f=new FormData(event.currentTarget),kcal=Math.max(0,Number(f.get('kcal'))||0);if(!kcal){toast('Nhập lượng kcal của món ăn');return}gymData.nutrition.unshift({id:Date.now(),date:new Date().toISOString(),name:(f.get('name')||'Bữa ăn').trim(),kcal,protein:Math.max(0,Number(f.get('protein'))||0),carbs:Math.max(0,Number(f.get('carbs'))||0),fat:Math.max(0,Number(f.get('fat'))||0)});persist();toast('Đã ghi nhận bữa ăn');nutritionPage()}
function removeFood(id){gymData.nutrition=gymData.nutrition.filter(x=>x.id!==id);persist();nutritionPage()}
function nutritionPage(){state.tab='nutrition';const t=nutritionTargets(),e=todayNutrition(),u=gymData.user,remaining=t.calories-e.kcal,menu=u.goal==='Giảm mỡ'?[['Sáng','Yến mạch, sữa chua không đường, trái cây'],['Trưa','Cơm vừa phần, ức gà/cá, nhiều rau'],['Tối','Đạm nạc, rau, tinh bột vừa phải'],['Phụ','Trái cây hoặc sữa chua giàu protein']]:u.goal==='Tăng cơ'?[['Sáng','Yến mạch, trứng, sữa hoặc sữa chua'],['Trưa','Cơm, thịt/cá, rau và chất béo tốt'],['Tối','Tinh bột, đạm nạc, rau củ'],['Phụ','Sữa, chuối, hạt hoặc sandwich']]:[['Sáng','Nguồn đạm + ngũ cốc nguyên hạt'],['Trưa','Đạm nạc, tinh bột và rau'],['Tối','Bữa cân bằng, ưu tiên rau'],['Phụ','Trái cây, hạt hoặc sữa chua']];layout(`<p class="eyebrow">DINH DƯỠNG HÔM NAY</p><div class="title-row"><div><h1 class="page-title">Nạp năng lượng thông minh</h1><p class="subtitle">Mục tiêu ${esc(u.goal).toLowerCase()} · số liệu là điểm khởi đầu để tự điều chỉnh.</p></div><button class="secondary-btn" onclick="homeAuto()">← Trang chủ</button></div><section class="calorie-hero"><div><span>CALO CÒN LẠI</span><strong>${Math.max(0,remaining).toLocaleString('vi-VN')} kcal</strong><p>Đã nạp ${e.kcal.toLocaleString('vi-VN')} / ${t.calories.toLocaleString('vi-VN')} kcal</p></div><div class="calorie-ring" style="--progress:${Math.min(100,Math.round(e.kcal/t.calories*100))}%"><b>${Math.min(100,Math.round(e.kcal/t.calories*100))}%</b></div></section><div class="macro-grid"><div><b>${e.protein}/${t.protein}g</b><span>Protein</span></div><div><b>${e.carbs}/${t.carbs}g</b><span>Carb</span></div><div><b>${e.fat}/${t.fat}g</b><span>Chất béo</span></div></div><section class="meal-plan"><div class="section-head"><h2>Thực đơn gợi ý</h2><span>Ưu tiên thực phẩm bạn hợp và dễ duy trì</span></div>${menu.map(([time,text])=>`<article><b>${time}</b><p>${text}</p></article>`).join('')}</section><section class="food-log"><h2>Ghi bữa ăn</h2><form onsubmit="saveFood(event)"><input name="name" maxlength="50" placeholder="Ví dụ: Cơm gà" required><div class="nutrition-inputs"><label>Kcal<input name="kcal" type="number" min="0" placeholder="450" required></label><label>Protein (g)<input name="protein" type="number" min="0" placeholder="35"></label><label>Carb (g)<input name="carbs" type="number" min="0" placeholder="50"></label><label>Chất béo (g)<input name="fat" type="number" min="0" placeholder="12"></label></div><button class="primary-btn blue" type="submit">+ Ghi nhận bữa ăn</button></form></section><div class="section-head"><h2>Đã ăn hôm nay</h2></div>${gymData.nutrition.filter(x=>dayKey(x.date)===dayKey(new Date())).length?`<div class="food-history">${gymData.nutrition.filter(x=>dayKey(x.date)===dayKey(new Date())).map(x=>`<article><div><b>${esc(x.name)}</b><small>${x.kcal} kcal · P ${x.protein}g · C ${x.carbs}g · F ${x.fat}g</small></div><button onclick="removeFood(${x.id})">×</button></article>`).join('')}</div>`:'<p class="subtitle">Chưa có bữa ăn nào được ghi hôm nay.</p>'}<p class="nutrition-disclaimer">Thông tin này không thay thế tư vấn của bác sĩ hoặc chuyên gia dinh dưỡng, nhất là khi bạn có bệnh lý, đang mang thai hoặc có tiền sử rối loạn ăn uống.</p>`)}
const homeBeforeStreak=homeAuto;
homeAuto=function(){homeBeforeStreak();const hero=document.querySelector('.home-hero');if(!hero)return;const streak=trainingStreak(),level=Math.min(5,Math.max(1,Math.ceil(streak/3))),message=streak?`Tuyệt vời! Bạn đang duy trì ${streak} ngày liên tiếp.`:'Hoàn thành buổi tập đầu tiên để thắp lên ngọn lửa.';hero.insertAdjacentHTML('beforebegin',`<section class="streak-card level-${level}"><div class="streak-flame" aria-hidden="true">🔥</div><div><span>CHUỖI TẬP LUYỆN</span><h2>${streak} ngày liên tiếp</h2><p>${message}</p></div><button onclick="nutritionPage()"><b>🍽</b><small>Dinh dưỡng</small></button></section>`)};

// Chụp ảnh bữa ăn và ước tính sơ bộ do người dùng xác nhận trước khi lưu.
let pendingMealPhoto='';
const mealEstimateTable={rice:{name:'Cơm + thịt + rau',kcal:550,protein:32,carbs:65,fat:17},noodle:{name:'Phở / bún / mì',kcal:480,protein:25,carbs:62,fat:14},salad:{name:'Salad + nguồn đạm',kcal:360,protein:28,carbs:24,fat:16},bread:{name:'Bánh mì / sandwich',kcal:430,protein:20,carbs:52,fat:15},snack:{name:'Đồ ăn nhẹ / đồ uống',kcal:230,protein:9,carbs:32,fat:8},other:{name:'Bữa ăn tự chọn',kcal:450,protein:25,carbs:50,fat:15}};
function resizeMealPhoto(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{const scale=Math.min(1,720/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.72))};img.src=reader.result};reader.readAsDataURL(file)})}
async function previewMealPhoto(event){const file=event.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Hãy chọn một ảnh bữa ăn');return}try{pendingMealPhoto=await resizeMealPhoto(file);const preview=document.querySelector('.meal-photo-preview');if(preview){preview.src=pendingMealPhoto;preview.hidden=false}document.querySelector('.photo-status').textContent='Ảnh đã sẵn sàng để ước tính';toast('Đã thêm ảnh bữa ăn')}catch{toast('Không thể đọc ảnh này')}}
function applyMealEstimate(){const type=document.querySelector('[name="mealType"]')?.value||'other',portion=Number(document.querySelector('[name="portion"]')?.value||1),base=mealEstimateTable[type]||mealEstimateTable.other,form=document.querySelector('.food-log form');if(!form)return;form.elements.name.value=base.name;form.elements.kcal.value=Math.round(base.kcal*portion);form.elements.protein.value=Math.round(base.protein*portion);form.elements.carbs.value=Math.round(base.carbs*portion);form.elements.fat.value=Math.round(base.fat*portion);toast('Đã điền ước tính — bạn có thể chỉnh lại trước khi lưu')}
saveFood=function(event){event.preventDefault();const f=new FormData(event.currentTarget),kcal=Math.max(0,Number(f.get('kcal'))||0);if(!kcal){toast('Nhập lượng kcal của món ăn');return}gymData.nutrition.unshift({id:Date.now(),date:new Date().toISOString(),name:(f.get('name')||'Bữa ăn').trim(),kcal,protein:Math.max(0,Number(f.get('protein'))||0),carbs:Math.max(0,Number(f.get('carbs'))||0),fat:Math.max(0,Number(f.get('fat'))||0),photo:pendingMealPhoto||''});pendingMealPhoto='';persist();toast('Đã ghi nhận bữa ăn');nutritionPage()};
const nutritionPageBeforePhoto=nutritionPage;
nutritionPage=function(){nutritionPageBeforePhoto();const form=document.querySelector('.food-log form');if(!form)return;form.insertAdjacentHTML('afterbegin',`<div class="meal-photo-tool"><div class="photo-picker"><label class="photo-button">📷 Chụp / chọn ảnh<input type="file" accept="image/*" capture="environment" onchange="previewMealPhoto(event)"></label><img class="meal-photo-preview" ${pendingMealPhoto?'':'hidden'} src="${pendingMealPhoto}" alt="Ảnh bữa ăn"><span class="photo-status">${pendingMealPhoto?'Ảnh đã sẵn sàng để ước tính':'Chưa có ảnh bữa ăn'}</span></div><div class="photo-estimator"><label>Loại món<select name="mealType">${Object.entries(mealEstimateTable).map(([id,m])=>`<option value="${id}">${m.name}</option>`).join('')}</select></label><label>Khẩu phần<select name="portion"><option value=".75">Nhỏ</option><option value="1" selected>Vừa</option><option value="1.35">Lớn</option></select></label><button type="button" onclick="applyMealEstimate()">✦ Ước tính từ ảnh</button></div><p>Ước tính dựa trên ảnh, nhóm món và khẩu phần bạn chọn. Hãy chỉnh số liệu nếu bạn biết thành phần hoặc khối lượng thực tế.</p></div>`);const todayItems=gymData.nutrition.filter(x=>dayKey(x.date)===dayKey(new Date())),rows=document.querySelectorAll('.food-history article');todayItems.forEach((item,i)=>{if(item.photo&&rows[i])rows[i].insertAdjacentHTML('afterbegin',`<img class="food-thumb" src="${item.photo}" alt="${esc(item.name)}">`)})};

function nutritionPlanOptions(){const goal=gymData.user.goal;if(goal==='Tăng cơ')return[{id:'gain-4',name:'Tăng cơ 4 bữa',note:'Dễ đạt đủ protein và năng lượng',meals:[['Sáng',.25,'Yến mạch, trứng, sữa chua hoặc sữa'],['Trưa',.30,'Cơm, thịt/cá, rau và chất béo tốt'],['Quanh buổi tập',.20,'Chuối + sữa / whey hoặc sandwich'],['Tối',.25,'Tinh bột, đạm nạc, rau củ'] ]},{id:'gain-3',name:'Tăng cơ 3 bữa',note:'Phù hợp lịch bận rộn',meals:[['Sáng',.30,'Bánh mì trứng hoặc yến mạch giàu đạm'],['Trưa',.38,'Cơm, thịt/cá/đậu, rau'],['Tối',.32,'Cơm/khoai, đạm nạc, rau']]}];if(goal==='Giảm mỡ')return[{id:'cut-3',name:'Giảm mỡ no lâu',note:'Ưu tiên đạm, rau và chất xơ',meals:[['Sáng',.28,'Trứng/sữa chua, yến mạch, trái cây'],['Trưa',.38,'Đạm nạc, cơm vừa phần, nhiều rau'],['Tối',.24,'Cá/đậu/ức gà, rau, tinh bột vừa phải'],['Phụ',.10,'Trái cây hoặc sữa chua giàu protein']]},{id:'cut-training',name:'Giảm mỡ có tập luyện',note:'Dồn carb gần buổi tập',meals:[['Sáng',.25,'Đạm + ngũ cốc nguyên hạt'],['Trước tập',.15,'Chuối hoặc bánh mì nguyên cám'],['Sau tập / trưa',.38,'Cơm/khoai, đạm nạc, rau'],['Tối',.22,'Đạm nạc và nhiều rau']]}];if(goal==='Tăng sức mạnh')return[{id:'strength-4',name:'Sức mạnh quanh buổi tập',note:'Năng lượng ổn định cho buổi tập nặng',meals:[['Sáng',.25,'Yến mạch, trứng, trái cây'],['Trưa',.30,'Cơm, thịt/cá, rau'],['Trước hoặc sau tập',.20,'Carb dễ tiêu + protein'],['Tối',.25,'Tinh bột, đạm nạc, rau củ']]}];return[{id:'balance-3',name:'Cân bằng mỗi ngày',note:'Dễ duy trì lâu dài',meals:[['Sáng',.30,'Đạm, trái cây và ngũ cốc nguyên hạt'],['Trưa',.40,'Nửa đĩa rau, đạm, tinh bột'],['Tối',.30,'Bữa cân bằng, hạn chế ăn quá muộn']]},{id:'balance-4',name:'Cân bằng 4 bữa',note:'Chia nhỏ năng lượng trong ngày',meals:[['Sáng',.25,'Nguồn đạm + carb chất lượng'],['Trưa',.30,'Đạm nạc, cơm/khoai, rau'],['Phụ',.15,'Trái cây, hạt hoặc sữa chua'],['Tối',.30,'Rau, đạm và tinh bột vừa đủ']]}]}
function chooseNutritionPlan(id){state.nutritionPlan=id;nutritionPage()}

// Khảo sát đầu vào: dùng để tạo đề xuất lịch tập thay vì buộc mọi người theo một mẫu chung.
function experienceRank(value){return({'Người mới':1,'Đã tập cơ bản':2,'Trung cấp':3,'Nâng cao':4}[value]||1)}
function scheduleExamples(){const u=gymData.user,a=gymData.assessment||{},targetDays=Math.min(7,Math.max(1,Number(u.days)||3)),targetLevel=experienceRank(a.experience);return trainingSchedules.map(plan=>{const rank=experienceRank(plan.level),audience=plan.audience||'Mọi người';let score=Math.abs(plan.days-targetDays)*2+(plan.goal===u.goal?0:4)+Math.abs(rank-targetLevel);if(a.equipment==='Không dụng cụ'&&!/tại nhà|phục hồi|khởi động/i.test(plan.name))score+=2;if(a.focus&&a.focus!=='Mọi người'&&audience!==a.focus&&audience!=='Mọi người')score+=2;return{...plan,score}}).sort((x,y)=>x.score-y.score).slice(0,3)}
function onboardingPage(){state.tab='survey';const u=gymData.user,a=gymData.assessment||{};layout(`<section class="onboarding-hero"><span>GYMAI · CÁ NHÂN HÓA</span><h1>Hãy bắt đầu bằng vài thông tin về bạn.</h1><p>Chúng tôi dùng khảo sát này để đề xuất lịch tập vừa sức, không thay thế chẩn đoán hay tư vấn y tế.</p></section><form class="onboarding-form" onsubmit="finishOnboarding(event)"><div class="survey-step"><i>01</i><div><h2>Mục tiêu & thói quen</h2><p>Chọn mục tiêu bạn muốn ưu tiên trong 8–12 tuần tới.</p></div></div><label>Tên bạn<input name="name" maxlength="30" value="${esc(u.name||'')}" required></label><div class="survey-grid"><label>Mục tiêu<select name="goal">${['Tăng cơ','Giảm mỡ','Tăng sức mạnh','Duy trì sức khỏe'].map(x=>`<option ${x===u.goal?'selected':''}>${x}</option>`).join('')}</select></label><label>Định hướng lịch tập<select name="focus">${['Mọi người','Nam','Nữ'].map(x=>`<option ${x===(u.focus||'Mọi người')?'selected':''}>${x}</option>`).join('')}</select></label><label>Trình độ hiện tại<select name="experience">${['Người mới','Đã tập cơ bản','Trung cấp','Nâng cao'].map(x=>`<option ${x===(a.experience||'Người mới')?'selected':''}>${x}</option>`).join('')}</select></label><label>Số buổi / tuần<select name="days">${[1,2,3,4,5,6,7].map(x=>`<option value="${x}" ${x===Number(u.days||3)?'selected':''}>${x} buổi</option>`).join('')}</select></label></div><div class="survey-step"><i>02</i><div><h2>Thể trạng & điều kiện tập</h2><p>Thông tin chỉ dùng để chọn lịch có cường độ phù hợp.</p></div></div><div class="survey-grid"><label>Tuổi<input name="age" type="number" min="16" max="90" value="${a.age||''}" placeholder="Ví dụ: 25" required></label><label>Chiều cao (cm)<input name="height" type="number" min="100" max="250" value="${u.height||''}" required></label><label>Cân nặng (kg)<input name="weight" type="number" min="25" max="350" value="${u.weight||''}" required></label><label>Thời lượng / buổi<select name="duration">${['30 phút','45 phút','60 phút','75+ phút'].map(x=>`<option ${x===(a.duration||'45 phút')?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="survey-grid"><label>Thiết bị hiện có<select name="equipment">${['Phòng gym đầy đủ','Tạ đơn / ghế tập','Dây kháng lực','Không dụng cụ'].map(x=>`<option ${x===(a.equipment||'Phòng gym đầy đủ')?'selected':''}>${x}</option>`).join('')}</select></label><label>Lưu ý khi tập<select name="limitation">${['Không có lưu ý đặc biệt','Cần bắt đầu nhẹ / mới quay lại tập','Có chấn thương hoặc tình trạng cần hỏi chuyên gia'].map(x=>`<option ${x===(a.limitation||'Không có lưu ý đặc biệt')?'selected':''}>${x}</option>`).join('')}</select></label></div><button class="start-assessment" type="submit">Xem lịch tập phù hợp →</button><p class="survey-footnote">Bạn có thể cập nhật mục tiêu trong Hồ sơ bất cứ lúc nào.</p></form>`) }
function finishOnboarding(event){event.preventDefault();const d=new FormData(event.currentTarget);gymData.user={...gymData.user,name:(d.get('name')||'Bạn').trim()||'Bạn',goal:d.get('goal'),focus:d.get('focus'),height:Number(d.get('height'))||defaultUser.height,weight:Number(d.get('weight'))||defaultUser.weight,days:Number(d.get('days'))||3};gymData.assessment={age:Number(d.get('age'))||null,experience:d.get('experience'),duration:d.get('duration'),equipment:d.get('equipment'),limitation:d.get('limitation')};gymData.onboardingCompleted=true;persist();surveyResults()}
function surveyResults(){state.tab='survey';const u=gymData.user,a=gymData.assessment||{},plans=scheduleExamples(),warning=a.limitation==='Có chấn thương hoặc tình trạng cần hỏi chuyên gia';layout(`<section class="assessment-result"><span>✓ KHẢO SÁT HOÀN TẤT</span><h1>Lịch tập phù hợp với ${esc(u.name)}</h1><p>${u.goal} · ${a.experience} · ${u.days} buổi/tuần · ${a.duration||'45 phút'}/buổi</p><div class="assessment-pills"><b>${a.equipment||'Phòng gym đầy đủ'}</b><b>${u.focus||'Mọi người'}</b><b>${u.height} cm · ${u.weight} kg</b></div>${warning?'<div class="assessment-warning">Hãy ưu tiên kỹ thuật, bắt đầu với mức nhẹ và tham khảo chuyên gia phù hợp trước khi tập nặng.</div>':''}</section><div class="section-head"><h2>3 lịch nên cân nhắc</h2><span>Chọn một lịch để bắt đầu chỉnh buổi tập</span></div><div class="assessment-plans">${plans.map((plan,index)=>`<article class="assessment-plan ${index===0?'top':''}">${index===0?'<em>PHÙ HỢP NHẤT</em>':''}<div><span>${plan.level} · ${plan.days} buổi/tuần</span><h2>${plan.name}</h2><p>${plan.summary}</p><small>${plan.plan.map(day=>day[0]).join(' · ')}</small></div><button onclick="selectSurveySchedule('${plan.id}')">Chọn lịch</button></article>`).join('')}</div><button class="secondary-btn assessment-home" onclick="homeAuto()">Xem trang tổng quan</button><button class="text-link" onclick="onboardingPage()">← Làm lại khảo sát</button>`) }
function selectSurveySchedule(id){activateTrainingSchedule(id)}
const homeBeforeOnboarding=homeAuto;
homeAuto=function(){if(!gymData.onboardingCompleted){onboardingPage();return}homeBeforeOnboarding()};
const goBeforeOnboarding=go;
go=function(tab){if(!gymData.onboardingCompleted){onboardingPage();return}goBeforeOnboarding(tab)};
const nutritionPageBeforePlans=nutritionPage;
nutritionPage=function(){nutritionPageBeforePlans();const options=nutritionPlanOptions(),selected=options.find(x=>x.id===state.nutritionPlan)||options[0],target=nutritionTargets(),anchor=document.querySelector('.meal-plan');if(!anchor)return;anchor.insertAdjacentHTML('beforebegin',`<section class="nutrition-plans"><div class="section-head"><h2>Kế hoạch ăn theo mục tiêu</h2><span>${target.calories.toLocaleString('vi-VN')} kcal/ngày</span></div><div class="nutrition-plan-tabs">${options.map(plan=>`<button class="${plan.id===selected.id?'active':''}" onclick="chooseNutritionPlan('${plan.id}')"><b>${plan.name}</b><small>${plan.note}</small></button>`).join('')}</div><div class="daily-plan"><div><span>KẾ HOẠCH ĐANG CHỌN</span><h3>${selected.name}</h3><p>${selected.note}</p></div><strong>${target.protein}g protein</strong>${selected.meals.map(([time,portion,food])=>`<article><b>${time}</b><div><strong>~${Math.round(target.calories*portion)} kcal</strong><small>${food}</small></div></article>`).join('')}<p class="daily-plan-note">Tổng các bữa là mục tiêu ước tính. Điều chỉnh khẩu phần theo mức no, tiến độ và phản hồi cơ thể.</p></div></section>`)};

// Khảo sát mở rộng: chỉ phân loại mức sẵn sàng tập luyện phổ thông, không chẩn đoán y khoa.
const surveyWeekdays=[['T2','Thứ 2'],['T3','Thứ 3'],['T4','Thứ 4'],['T5','Thứ 5'],['T6','Thứ 6'],['T7','Thứ 7'],['CN','Chủ nhật']];
function safeAvailableDays(a){return Array.isArray(a.availableDays)&&a.availableDays.length?a.availableDays:['T2','T4','T6']}
function readinessInfo(a){const high=a.readiness==='Có bệnh nền, đang dùng thuốc, đau ngực, chóng mặt hoặc được dặn hạn chế vận động';const caution=a.readiness==='Có đau/ chấn thương kéo dài, mới ốm hoặc mới quay lại tập';if(high)return{tone:'care',title:'Nên hỏi chuyên gia trước khi bắt đầu',note:'GymAI không thể đánh giá an toàn tập luyện cho tình trạng này. Hãy nhận tư vấn từ bác sĩ hoặc chuyên gia phù hợp trước khi tập nặng.'};if(caution)return{tone:'caution',title:'Bắt đầu thận trọng',note:'Ưu tiên bài kỹ thuật nhẹ, giảm tải và dừng lại nếu đau tăng, chóng mặt hoặc khó chịu.'};return{tone:'ready',title:'Có thể bắt đầu theo mức nhẹ',note:'Bắt đầu ở mức vừa sức, tập trung kỹ thuật và tăng khối lượng từ từ theo phản hồi cơ thể.'}}
function suggestedDays(a,days){const available=safeAvailableDays(a),limit=a.readiness==='Có bệnh nền, đang dùng thuốc, đau ngực, chóng mặt hoặc được dặn hạn chế vận động'?Math.min(days,2):a.readiness==='Có đau/ chấn thương kéo dài, mới ốm hoặc mới quay lại tập'?Math.min(days,3):days;return available.slice(0,Math.max(1,Math.min(limit,available.length)))}
function scheduleExamples(){const u=gymData.user,a=gymData.assessment||{},targetDays=suggestedDays(a,Math.min(7,Math.max(1,Number(u.days)||3))).length,targetLevel=experienceRank(a.experience);return trainingSchedules.map(plan=>{const rank=experienceRank(plan.level),audience=plan.audience||'Mọi người';let score=Math.abs(plan.days-targetDays)*2+(plan.goal===u.goal?0:4)+Math.abs(rank-targetLevel);if(a.equipment==='Không dụng cụ'&&!/tại nhà|phục hồi|khởi động/i.test(plan.name))score+=2;if(a.focus&&a.focus!=='Mọi người'&&audience!==a.focus&&audience!=='Mọi người')score+=2;if(a.duration==='30 phút'&&plan.days>4)score+=2;return{...plan,score}}).sort((x,y)=>x.score-y.score).slice(0,3)}
function onboardingPage(){state.tab='survey';const u=gymData.user,a=gymData.assessment||{},available=safeAvailableDays(a);layout(`<section class="onboarding-hero"><span>GYMAI · KHẢO SÁT CÁ NHÂN</span><h1>Thiết kế lịch tập theo nhịp sống của bạn.</h1><p>Hoàn thành trong khoảng 2 phút để nhận mức bắt đầu và lịch mẫu theo thời gian rảnh. Thông tin chỉ được lưu trên thiết bị này.</p></section><form class="onboarding-form onboarding-pro" onsubmit="finishOnboarding(event)"><div class="survey-step"><i>01</i><div><h2>Bạn muốn đạt điều gì?</h2><p>Chọn ưu tiên cho 8–12 tuần tới.</p></div></div><label>Tên bạn<input name="name" maxlength="30" value="${esc(u.name||'')}" required></label><div class="survey-grid"><label>Mục tiêu<select name="goal">${['Tăng cơ','Giảm mỡ','Tăng sức mạnh','Duy trì sức khỏe'].map(x=>`<option ${x===u.goal?'selected':''}>${x}</option>`).join('')}</select></label><label>Định hướng lịch tập<select name="focus">${['Mọi người','Nam','Nữ'].map(x=>`<option ${x===(u.focus||'Mọi người')?'selected':''}>${x}</option>`).join('')}</select></label><label>Kinh nghiệm tập<select name="experience">${['Người mới','Đã tập cơ bản','Trung cấp','Nâng cao'].map(x=>`<option ${x===(a.experience||'Người mới')?'selected':''}>${x}</option>`).join('')}</select></label><label>Hoạt động thường ngày<select name="activity">${['Ít vận động / ngồi nhiều','Đi lại vừa phải','Vận động nhiều'].map(x=>`<option ${x===(a.activity||'Ít vận động / ngồi nhiều')?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="survey-step"><i>02</i><div><h2>Thể trạng & mức sẵn sàng</h2><p>Giúp chọn cường độ mở đầu. Không dùng để chẩn đoán.</p></div></div><div class="survey-grid"><label>Tuổi<input name="age" type="number" min="16" max="90" value="${a.age||''}" placeholder="Ví dụ: 25" required></label><label>Chiều cao (cm)<input name="height" type="number" min="100" max="250" value="${u.height||''}" required></label><label>Cân nặng (kg)<input name="weight" type="number" min="25" max="350" value="${u.weight||''}" required></label><label>Giấc ngủ thường ngày<select name="sleep">${['Dưới 6 giờ','6–7 giờ','7–9 giờ','Trên 9 giờ'].map(x=>`<option ${x===(a.sleep||'7–9 giờ')?'selected':''}>${x}</option>`).join('')}</select></label></div><label>Mức sẵn sàng vận động<select name="readiness">${['Không có lưu ý đặc biệt','Có đau/ chấn thương kéo dài, mới ốm hoặc mới quay lại tập','Có bệnh nền, đang dùng thuốc, đau ngực, chóng mặt hoặc được dặn hạn chế vận động'].map(x=>`<option ${x===(a.readiness||'Không có lưu ý đặc biệt')?'selected':''}>${x}</option>`).join('')}</select></label><label>Ghi chú tùy chọn (vùng cần tránh hoặc điều bạn muốn lưu ý)<input name="healthNote" maxlength="140" value="${esc(a.healthNote||'')}" placeholder="Ví dụ: cổ tay phải nhạy cảm khi chống đẩy"></label><p class="survey-disclaimer">Nếu có đau ngực, ngất/chóng mặt, khó thở bất thường, chấn thương cấp tính hoặc chỉ định hạn chế vận động, đừng tự bắt đầu buổi nặng — hãy hỏi chuyên gia y tế.</p><div class="survey-step"><i>03</i><div><h2>Thời gian thực tế của bạn</h2><p>Chọn các ngày có thể tập; lịch mẫu sẽ ưu tiên những ngày này.</p></div></div><div class="availability-days">${surveyWeekdays.map(([code,label])=>`<label><input type="checkbox" name="availableDays" value="${code}" ${available.includes(code)?'checked':''}><span>${label}</span></label>`).join('')}</div><div class="survey-grid"><label>Thời lượng / buổi<select name="duration">${['20–30 phút','45 phút','60 phút','75+ phút'].map(x=>`<option ${x===(a.duration||'45 phút')?'selected':''}>${x}</option>`).join('')}</select></label><label>Khung giờ thuận tiện<select name="timePreference">${['Sáng (05:00–09:00)','Trưa (11:00–14:00)','Chiều/tối (17:00–21:00)','Linh hoạt'].map(x=>`<option ${x===(a.timePreference||'Linh hoạt')?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="survey-step"><i>04</i><div><h2>Không gian tập</h2><p>Chúng tôi sẽ ưu tiên các bài phù hợp với dụng cụ bạn có.</p></div></div><label>Thiết bị hiện có<select name="equipment">${['Phòng gym đầy đủ','Tạ đơn / ghế tập','Dây kháng lực','Không dụng cụ'].map(x=>`<option ${x===(a.equipment||'Phòng gym đầy đủ')?'selected':''}>${x}</option>`).join('')}</select></label><button class="start-assessment" type="submit">Nhận đánh giá & lịch mẫu →</button><p class="survey-footnote">Bạn có thể chỉnh toàn bộ thông tin này bất cứ lúc nào trong Hồ sơ.</p></form>`) }
function finishOnboarding(event){event.preventDefault();const d=new FormData(event.currentTarget),available=d.getAll('availableDays');if(!available.length){toast('Hãy chọn ít nhất một ngày có thể tập');return}gymData.user={...gymData.user,name:(d.get('name')||'Bạn').trim()||'Bạn',goal:d.get('goal'),focus:d.get('focus'),height:Number(d.get('height'))||defaultUser.height,weight:Number(d.get('weight'))||defaultUser.weight,days:available.length};gymData.assessment={age:Number(d.get('age'))||null,experience:d.get('experience'),activity:d.get('activity'),sleep:d.get('sleep'),readiness:d.get('readiness'),healthNote:(d.get('healthNote')||'').trim(),availableDays:available,duration:d.get('duration'),timePreference:d.get('timePreference'),equipment:d.get('equipment')};gymData.onboardingCompleted=true;persist();surveyResults()}
function surveyResults(){state.tab='survey';const u=gymData.user,a=gymData.assessment||{},readiness=readinessInfo(a),days=suggestedDays(a,u.days),plans=scheduleExamples(),labels=days.map(code=>surveyWeekdays.find(x=>x[0]===code)?.[1]||code);layout(`<section class="assessment-result"><span>✓ KHẢO SÁT HOÀN TẤT</span><h1>Lộ trình mở đầu cho ${esc(u.name)}</h1><p>${u.goal} · ${a.experience} · ${a.duration||'45 phút'}/buổi · ${a.timePreference||'Linh hoạt'}</p><div class="assessment-pills"><b>${a.equipment||'Phòng gym đầy đủ'}</b><b>${a.sleep||'—'}/đêm</b><b>${u.height} cm · ${u.weight} kg</b></div></section><section class="readiness-card ${readiness.tone}"><span>ĐÁNH GIÁ SƠ BỘ</span><h2>${readiness.title}</h2><p>${readiness.note}</p>${a.healthNote?`<small>Ghi chú của bạn: ${esc(a.healthNote)}</small>`:''}</section><section class="weekly-suggestion"><div><span>LỊCH THEO THỜI GIAN RẢNH</span><h2>${days.length} buổi/tuần · ${a.timePreference||'Linh hoạt'}</h2><p>${labels.join(' · ')}. Các ngày còn lại ưu tiên nghỉ, đi bộ nhẹ hoặc giãn cơ.</p></div><div class="week-pills">${surveyWeekdays.map(([code,label])=>`<b class="${days.includes(code)?'training':''}">${label.replace('Thứ ','T')}</b>`).join('')}</div></section><div class="section-head"><h2>3 lịch nên cân nhắc</h2><span>Chọn một lịch để tạo buổi tập</span></div><div class="assessment-plans">${plans.map((plan,index)=>`<article class="assessment-plan ${index===0?'top':''}">${index===0?'<em>PHÙ HỢP NHẤT</em>':''}<div><span>${plan.level} · ${plan.days} buổi/tuần</span><h2>${plan.name}</h2><p>${plan.summary}</p><small>${plan.plan.map((day,i)=>`${labels[i]||`Buổi ${i+1}`}: ${day[0]}`).join(' · ')}</small></div><button onclick="selectSurveySchedule('${plan.id}')">Chọn lịch</button></article>`).join('')}</div><button class="secondary-btn assessment-home" onclick="homeAuto()">Xem trang tổng quan</button><button class="text-link" onclick="onboardingPage()">← Làm lại khảo sát</button>`) }
